// Kinesiology topics for Dr. MGR BPT Biomechanics, Applied Anatomy and Kinesiology (joint complexes, posture, gait). Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"bk-shoulder-joints", title:"Joints of the shoulder complex: SC, AC, scapulothoracic and glenohumeral", subject:"Kinesiology", region:"Shoulder", stages:"steps",
  aliases:["shoulder complex joints","sternoclavicular joint","acromioclavicular joint","scapulothoracic articulation","glenohumeral joint","shoulder girdle"],
  simple:"The shoulder is not one joint but a team of four: the sternoclavicular joint links the clavicle to the trunk, the acromioclavicular joint links clavicle to scapula, the scapula glides on the chest wall, and the humeral head turns in the glenoid. Together they give the arm the largest range of any body part. If any one joint is stiff or weak, the others must compensate.",
  flow:["Sternoclavicular joint is the only bony link to the trunk","Clavicle elevates, protracts and rotates backward","Acromioclavicular joint fine-tunes scapular rotation and tilt","Scapula glides and upwardly rotates on the thorax","Glenohumeral joint gives most of the arm range","All four move together for full elevation"],
  exam:[
    {h:"Introduction", p:["The shoulder complex has three anatomical joints (sternoclavicular, acromioclavicular, glenohumeral) and one functional joint (scapulothoracic); some authors add the suprahumeral (subacromial) space.","Its design trades stability for mobility; arm elevation needs coordinated motion of all components."]},
    {h:"Sternoclavicular (SC) joint", p:["Type: synovial saddle joint with an articular disc (fibrocartilage) that absorbs force from the clavicle and acts as a hinge for elevation-depression.","Ligaments: anterior and posterior sternoclavicular, interclavicular and costoclavicular (strongest restraint to elevation).","Motions: elevation about 45 degrees and depression about 10-15 degrees; protraction and retraction about 15-20 degrees each; posterior long-axis rotation of the clavicle up to about 50 degrees during full arm elevation."]},
    {h:"Acromioclavicular (AC) joint", p:["Type: plane synovial joint, often with an incomplete disc; joint surfaces are small and incongruent.","Stability comes from the superior and inferior AC ligaments (horizontal stability) and the coracoclavicular ligament: conoid (vertical restraint, pulls clavicle into posterior rotation) and trapezoid (resists medial override).","Motions: small upward-downward rotation, internal-external rotation and anterior-posterior tilting of the scapula on the clavicle, which keep the glenoid facing the humeral head."]},
    {h:"Scapulothoracic articulation", p:["Physiological joint: scapula glides on serratus anterior and subscapularis over the thorax; no true joint capsule.","Resting position: between T2 and T7 spinous levels, medial border about 5-7 cm from the spine, internally rotated about 30-40 degrees (plane of scapula), slightly anteriorly tilted and slightly upwardly rotated.","Motions: elevation-depression, protraction-retraction, upward-downward rotation (about 50-60 degrees of upward rotation during full elevation), anterior-posterior tilt and internal-external rotation."]},
    {h:"Glenohumeral (GH) joint", p:["Type: ball and socket synovial joint with 3 degrees of freedom; head is about three times the area of the glenoid.","Humeral head: angle of inclination about 130-150 degrees, retroverted about 30 degrees; glenoid faces anterolaterally and is slightly upwardly tilted.","Static stabilisers: labrum (deepens fossa), capsule, superior, middle and inferior glenohumeral ligaments, coracohumeral ligament, negative intra-articular pressure.","Range: flexion 0-180, extension 0-60, abduction 0-180 (with scapular motion), medial rotation 70-90, lateral rotation 90 degrees; close-packed in full abduction with lateral rotation."]},
    {h:"Integrated function and applied aspects", p:["Scapulohumeral rhythm: about 2 degrees GH to 1 degree scapulothoracic motion overall during elevation.","Applied: SC dislocation (posterior is dangerous to great vessels), AC separation (step deformity, graded by Rockwood), scapular dyskinesis, GH dislocation (mostly anterior-inferior).","Physiotherapy: assess all four joints, not just GH; restore clavicular and scapular mobility before forcing overhead range."]},
    {h:"Conclusion", p:["The shoulder complex works as a linked chain; full painless elevation needs mobile SC and AC joints, a stable well-controlled scapula and a centred humeral head."]}
  ],
  tip:"Draw an anterior view of the thorax with clavicle, scapula and humerus. Label SC joint with disc, AC joint with conoid and trapezoid ligaments, the scapula on the chest wall and the GH joint. Add a small arrow showing clavicular posterior rotation.",
  evidence:[["Scapular stabilisation exercise in shoulder pain","Improves scapular control and function in many patients","Moderate"],["Clavicular and AC joint mobilisation in stiff shoulder","Clinical rationale, limited trial data","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System",
  outcomes:[["Goniometry of shoulder elevation","Combined GH and scapular range"],["Lateral scapular slide test","Scapular position asymmetry"],["SPADI","Shoulder pain and disability"]],
  recent:["Three-dimensional motion analysis and dynamic imaging are increasingly used to study clavicular and scapular kinematics rather than relying only on two-dimensional ratios."],
  mnemonic:{word:"SAGS", items:[["S","Sternoclavicular: saddle with disc"],["A","Acromioclavicular: plane, held by coracoclavicular"],["G","Glenohumeral: ball and socket"],["S","Scapulothoracic: physiological glide"]], extra:"Only the SC joint attaches the upper limb to the axial skeleton."},
  example:"A 22-year-old kabaddi player in Salem falls on the tip of his shoulder and has a step at the AC joint. He can lift the arm only to 100 degrees because the scapula cannot rotate normally on the clavicle.",
  flags:["Posterior SC dislocation with breathlessness or dysphagia: vascular or tracheal compression","Recurrent GH dislocation with numbness: axillary nerve injury","Winging after surgery or trauma: long thoracic nerve palsy"],
  viva:[["Which ligament is the strongest restraint of the SC joint?","The costoclavicular ligament, which limits clavicular elevation."],["Why is the scapulothoracic joint called physiological?","It has no true synovial articulation; the scapula glides over muscles on the thorax."],["What is the close-packed position of the GH joint?","Full abduction with lateral rotation."]],
  refs:[{b:"levangie", ch:"The Shoulder Complex"},{b:"neumann", ch:"Shoulder Complex"},{b:"brunnstrom", ch:"Shoulder Region"}],
  keywords:["sternoclavicular","acromioclavicular","scapulothoracic","glenohumeral","coracoclavicular","shoulder girdle"],
  mcq:[["Which ligament mainly prevents vertical displacement of the clavicle at the AC joint?",["Trapezoid","Conoid","Superior AC","Costoclavicular"],1,"The conoid part of the coracoclavicular ligament is the main vertical restraint and helps produce posterior clavicular rotation."],["The resting scapula lies between which vertebral levels?",["C5-T2","T2-T7","T6-T12","T8-L1"],1,"The scapula normally spans about T2 to T7 on the posterior thorax."]]
},
{
  id:"bk-gh-dynamic-stability", title:"Dynamic stability of the glenohumeral joint", subject:"Kinesiology", region:"Shoulder", stages:"steps",
  aliases:["dynamic stabilisers shoulder","rotator cuff function","concavity compression","deltoid rotator cuff force couple","glenohumeral stability","shoulder instability"],
  simple:"The ball of the shoulder sits on a very shallow socket, so ligaments alone cannot hold it. Muscles, mainly the rotator cuff, keep pressing the head into the socket and steering it as the arm moves. This active control is called dynamic stability.",
  flow:["Shallow glenoid gives poor bony stability","Labrum and ligaments give static restraint at end range","Rotator cuff compresses head into the glenoid","Cuff depresses head against upward pull of deltoid","Biceps long head and scapular muscles add control","Proprioceptive reflexes fine-tune muscle timing"],
  exam:[
    {h:"Introduction", p:["GH stability = static (passive) stabilisers + dynamic (active) stabilisers.","Static restraints act mainly at end range; in mid range, where ligaments are lax, stability depends on muscles."]},
    {h:"Static stabilisers (brief)", p:["Glenoid labrum deepens the socket and increases contact area; bony glenoid orientation (slight upward tilt) resists inferior slip.","Superior GH and coracohumeral ligaments resist inferior translation with arm by side; middle GH ligament resists anterior translation in mid abduction; inferior GH ligament complex (anterior band) resists anterior-inferior translation at 90 degrees abduction with lateral rotation.","Negative intra-articular pressure and adhesion of synovial fluid."]},
    {h:"Dynamic stabilisers", p:["Rotator cuff (supraspinatus, infraspinatus, teres minor, subscapularis): compresses the humeral head into the glenoid (concavity compression) and centres it.","Deltoid-rotator cuff force couple: deltoid pulls the head upward; infraspinatus, teres minor and subscapularis pull it down and in, so the arm rotates instead of the head riding up.","Transverse force couple: subscapularis anteriorly balances infraspinatus and teres minor posteriorly.","Long head of biceps: depresses and stabilises the head, especially in abduction with lateral rotation.","Cuff tendons blend with the capsule, so muscle contraction tightens ligaments (dynamic ligament tension)."]},
    {h:"Role of the scapula and neuromuscular control", p:["Scapular muscles (serratus anterior, trapezius, rhomboids) position the glenoid under the humeral head, keeping the joint in a stable alignment.","Mechanoreceptors in capsule and ligaments trigger reflex cuff contraction; proprioceptive loss after dislocation contributes to recurrence."]},
    {h:"Clinical relevance", p:["Cuff weakness or tear allows superior migration of the head and subacromial impingement.","Atraumatic multidirectional instability is managed mainly by dynamic stabilisation training.","Physiotherapy: rotator cuff strengthening (isometrics progressing to elastic band, 2-3 sets of 10-15, daily or alternate days), scapular setting and serratus training, closed chain weight bearing, rhythmic stabilisation and proprioceptive drills, plyometrics for athletes."]},
    {h:"Conclusion", p:["The GH joint relies on muscle more than any other major joint; restoring cuff and scapular control is the core of conservative instability care."]}
  ],
  tip:"Draw the humeral head in the glenoid with a vertical arrow for deltoid pull and a downward-inward arrow for the cuff; show their resultant pressing the head into the glenoid. Label it concavity compression.",
  evidence:[["Exercise-based rehabilitation for atraumatic shoulder instability","Recommended first-line; improves function in many patients","Low to moderate"],["Rotator cuff and scapular strengthening after first-time anterior dislocation","Commonly used; recurrence remains high in young athletes","Low"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin, Joint Structure and Function; Cochrane reviews on shoulder instability rehabilitation",
  outcomes:[["Apprehension and relocation tests","Anterior instability"],["Sulcus sign","Inferior laxity"],["Hand-held dynamometry of rotators","Cuff strength"],["WOSI","Shoulder instability-specific quality of life"]],
  recent:["The Stanmore classification groups instability into traumatic structural, atraumatic structural and muscle patterning types to guide whether rehabilitation or surgery comes first."],
  mnemonic:{word:"CUFF", items:[["C","Compression of head into socket"],["U","Unopposed deltoid pull prevented"],["F","Force couples, vertical and transverse"],["F","Feedback from capsular receptors"]], extra:"Static restraints work at end range; dynamic restraints work throughout the range."},
  example:"A 19-year-old volleyball player in Chennai has recurrent shoulder slipping with no major injury. Rehabilitation focuses on rotator cuff and serratus anterior control with rhythmic stabilisation before any surgical opinion.",
  flags:["First-time dislocation over 40 years: check rotator cuff tear and axillary nerve","Locked dislocation or neurovascular signs: urgent referral","Voluntary dislocators with psychological overlay need special care"],
  viva:[["What is concavity compression?","Stability produced by compressing the convex humeral head into the concave glenoid by cuff contraction."],["Which part of the IGHL resists anterior dislocation in abduction and lateral rotation?","The anterior band of the inferior glenohumeral ligament complex."],["How does deltoid cause impingement if the cuff is weak?","Unopposed deltoid pulls the head upward against the coracoacromial arch."]],
  refs:[{b:"neumann", ch:"Shoulder Complex"},{b:"levangie", ch:"The Shoulder Complex"},{b:"brunnstrom", ch:"Shoulder Region"}],
  keywords:["dynamic stability","rotator cuff","force couple","concavity compression","instability","labrum"],
  mcq:[["Which muscle is NOT part of the rotator cuff?",["Supraspinatus","Teres minor","Teres major","Subscapularis"],2,"Teres major is not a cuff muscle; it does not blend with the capsule."],["Superior migration of the humeral head during abduction is mainly prevented by",["Upper trapezius","Infraspinatus, teres minor and subscapularis","Pectoralis minor","Coracobrachialis"],1,"The inferior cuff muscles depress the head, balancing the upward deltoid pull."]]
},
{
  id:"bk-shoulder-elevation-depression", title:"Muscles of elevation and depression of the shoulder complex", subject:"Kinesiology", region:"Shoulder", stages:"steps",
  aliases:["shoulder elevators","shoulder depressors","upward rotation force couple","serratus anterior trapezius","arm elevation muscles","scapular depressors"],
  simple:"Lifting the arm overhead needs muscles that move the humerus and muscles that rotate the scapula upward at the same time. Pushing down, as in crutch walking or getting up from a chair, uses strong depressor muscles that pull the arm and shoulder girdle down. Each action is done by teams of muscles working as force couples.",
  flow:["Deltoid and supraspinatus raise the humerus","Rotator cuff keeps the head centred","Trapezius and serratus anterior upwardly rotate the scapula","Depressors pull arm and scapula down","Latissimus and pectoralis lift the body on crutches","Weakness of any member alters shoulder rhythm"],
  exam:[
    {h:"Introduction", p:["Elevation of the arm (flexion, abduction or scaption) is produced by GH muscles plus scapulothoracic upward rotators.","Depression includes depression of the arm (adduction, extension against load) and of the shoulder girdle; it is functionally vital for transfers and crutch walking."]},
    {h:"Muscles of arm elevation (GH)", p:["Deltoid (axillary nerve, C5-C6): anterior and middle fibres are prime movers of flexion and abduction; produces about half of abduction torque.","Supraspinatus (suprascapular nerve): initiates and assists abduction throughout range and compresses the head.","Rotator cuff and long head of biceps stabilise the head; infraspinatus and teres minor laterally rotate the humerus so the greater tubercle clears the acromion in abduction.","Clavicular head of pectoralis major and coracobrachialis assist flexion."]},
    {h:"Scapular upward rotators and girdle elevators", p:["Upward rotation force couple: upper trapezius, lower trapezius and serratus anterior; serratus also holds the scapula against the thorax and posteriorly tilts it.","Girdle elevation (shrug): upper trapezius, levator scapulae, rhomboids; levator and rhomboids also downwardly rotate, so trapezius must dominate during arm raising.","Paralysis of serratus gives medial winging and loss of full elevation; trapezius palsy (spinal accessory nerve) gives drooping shoulder and lateral winging."]},
    {h:"Muscles of depression", p:["Arm depressors: latissimus dorsi (thoracodorsal nerve), sternal pectoralis major, teres major, long head of triceps; they adduct and extend the arm.","Girdle depressors: lower trapezius, pectoralis minor, subclavius, and latissimus acting through the humerus.","Closed chain: with hands fixed on crutches or chair arms, latissimus and pectoralis lift the trunk; this is critical for tetraplegics (C7) and paraplegics during transfers and push-ups."]},
    {h:"Clinical and physiotherapy relevance", p:["Strengthen serratus with wall push-up plus, punch plus and supine protraction; trapezius with prone Y, T, W raises (2-3 sets of 10-15).","Train depression (sitting push-ups, seated dips) before crutch walking; graded resistance 8-12 repetitions, progressive.","Avoid overactive upper trapezius during elevation exercises in impingement."]},
    {h:"Conclusion", p:["Normal elevation is a partnership of humeral movers and scapular rotators; depression strength decides independence in transfers and ambulation aids."]}
  ],
  tip:"Draw a posterior view of the scapula with three arrows: upper trapezius (up and medial), lower trapezius (down and medial) and serratus (lateral, around the chest). Show the axis near the AC joint later in range and label the force couple.",
  evidence:[["Serratus and lower trapezius strengthening in subacromial pain","Improves pain and function as part of exercise programmes","Moderate"],["Depression training before crutch use","Standard clinical practice, little trial data","Expert opinion"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin; Kendall, Muscles: Testing and Function",
  outcomes:[["Manual muscle testing","Grade of deltoid, serratus and depressors"],["Sitting push-up test","Functional depression strength"],["Scapular dyskinesis test","Quality of scapular motion"]],
  recent:["Electromyographic studies have been used to select exercises that bias lower trapezius and serratus over upper trapezius, such as side-lying external rotation and prone horizontal abduction."],
  mnemonic:{word:"UTS", items:[["U","Upper trapezius"],["T","lower Trapezius"],["S","Serratus anterior"]], extra:"UTS rotate the scapula up; for depression remember LPL: latissimus, pectoralis, lower trapezius."},
  example:"A 30-year-old man in Coimbatore with T10 paraplegia practices sitting push-ups on blocks to strengthen latissimus dorsi and pectoralis major before learning wheelchair-to-bed transfers.",
  flags:["Sudden winging with neck pain: brachial neuritis or nerve injury","Painful arc with weakness after fall: rotator cuff tear","Loss of shoulder depression strength in high SCI affects transfer safety"],
  viva:[["Which muscles form the upward rotation force couple?","Upper trapezius, lower trapezius and serratus anterior."],["Why is latissimus dorsi important in paraplegia?","In closed chain it depresses the shoulder girdle and lifts the trunk for transfers and crutch walking."],["Nerve supply of serratus anterior?","Long thoracic nerve (C5-C7)."]],
  refs:[{b:"neumann", ch:"Shoulder Complex"},{b:"levangie", ch:"The Shoulder Complex"},{b:"brunnstrom", ch:"Shoulder Region"}],
  keywords:["elevation","depression","serratus anterior","trapezius","latissimus dorsi","force couple"],
  mcq:[["Medial winging of the scapula is caused by weakness of",["Rhomboids","Serratus anterior","Levator scapulae","Teres major"],1,"Serratus anterior holds the medial border to the thorax; its palsy causes medial winging."],["Which muscle lifts the trunk during a sitting push-up?",["Supraspinatus","Upper trapezius","Latissimus dorsi","Deltoid middle fibres"],2,"In closed chain, latissimus dorsi depresses the shoulder girdle and raises the body."]]
},
{
  id:"bk-elbow-joints", title:"Elbow complex: humeroulnar, humeroradial and radioulnar joints", subject:"Kinesiology", region:"Elbow and forearm", stages:"steps",
  aliases:["elbow joint","humeroulnar joint","humeroradial joint","superior radioulnar joint","pronation supination","annular ligament","interosseous membrane"],
  simple:"The elbow complex has a hinge between the humerus and ulna, a button-like joint between humerus and radial head, and two pivot joints between radius and ulna. The hinge bends and straightens the arm, while the radius rolls around the ulna to turn the palm up and down. A tough membrane between the two forearm bones passes load from the hand to the elbow.",
  flow:["Humeroulnar hinge gives flexion and extension","Humeroradial joint shares both hinge and rotation","Proximal radioulnar joint spins radial head in annular ligament","Distal radioulnar joint lets radius swing around ulna","Interosseous membrane transfers load from radius to ulna","Collateral ligaments resist valgus and varus"],
  exam:[
    {h:"Introduction", p:["The elbow complex includes the elbow joint proper (humeroulnar and humeroradial, sharing one capsule) and the proximal and distal radioulnar joints.","Two degrees of freedom: flexion-extension and pronation-supination."]},
    {h:"Humeroulnar joint", p:["Uniaxial hinge (modified): trochlea of humerus with trochlear notch of ulna; very congruent, giving bony stability.","Axis passes through the centre of trochlea and capitulum, slightly oblique, producing the carrying angle.","Close-packed position: full extension with supination; range flexion 0-145 degrees (active), passive up to about 150-160."]},
    {h:"Humeroradial joint", p:["Capitulum with concave radial head; participates in both flexion-extension and spin during pronation-supination.","Transmits about half or more of axial load from the hand when the elbow is extended.","Close-packed position: about 90 degrees flexion with about 5 degrees supination."]},
    {h:"Radioulnar joints", p:["Proximal: pivot; radial head spins in the radial notch of ulna, held by the annular ligament (lined by cartilage) and quadrate ligament.","Distal: pivot; ulnar notch of radius moves around the ulnar head; triangular fibrocartilage complex (TFCC) is the main stabiliser.","Range: pronation about 75-80 degrees, supination about 80-90 degrees, measured with elbow at 90 degrees to exclude shoulder rotation.","Interosseous membrane: fibres run obliquely from radius proximally to ulna distally, transferring load from radius to ulna."]},
    {h:"Ligaments and muscles", p:["Medial (ulnar) collateral ligament: anterior bundle is the main valgus restraint; posterior and transverse bundles.","Lateral collateral complex: radial collateral, lateral ulnar collateral (posterolateral rotatory stability) and annular ligament.","Flexors: brachialis (workhorse, any forearm position), biceps (strong flexor and supinator), brachioradialis (mid-prone position). Extensors: triceps and anconeus.","Pronators: pronator teres and pronator quadratus. Supinators: supinator and biceps brachii (strongest with elbow at 90 degrees)."]},
    {h:"Applied aspects and conclusion", p:["Pulled elbow in children (radial head subluxes from annular ligament), tennis elbow, golfer's elbow, MCL injury in throwers, elbow stiffness after supracondylar fracture.","The elbow positions the hand in space; restoring flexion to about 130 degrees and 50 degrees each of pronation and supination covers most daily tasks."]}
  ],
  tip:"Draw an anterior view of the elbow showing trochlea with ulna, capitulum with radial head, annular ligament ring, and the interosseous membrane with oblique fibres. Add a small arrow showing load passing from radius to ulna.",
  evidence:[["Early active motion after stable elbow dislocation","Better early range and function than prolonged immobilisation","Moderate"],["Static progressive splinting for elbow stiffness","Improves range in many cases","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System",
  outcomes:[["Goniometry","Flexion, extension, pronation and supination range"],["DASH or QuickDASH","Upper limb function"],["Mayo Elbow Performance Score","Elbow-specific function"]],
  recent:["Studies of functional range suggest many modern tasks such as using a phone need more elbow flexion than the classically quoted 30-130 degree arc."],
  mnemonic:{word:"HRP", items:[["H","Hinge: humeroulnar"],["R","Rotate and roll: humeroradial"],["P","Pivots: proximal and distal radioulnar"]], extra:"Brachialis is the workhorse; biceps flexes best in supination."},
  example:"A 3-year-old in Madurai cries and refuses to use her arm after being lifted by the hand. The radial head has slipped from the annular ligament: a pulled elbow that the doctor reduces.",
  flags:["Swelling and pain after supracondylar fracture: watch for compartment syndrome","Massive swelling: brachial artery injury","Forced passive stretching of a stiff elbow can provoke myositis ossificans"],
  viva:[["Which ligament holds the radial head?","The annular ligament, attached to the anterior and posterior margins of the radial notch of ulna."],["What is the strongest supinator?","Biceps brachii, especially with the elbow flexed to 90 degrees."],["Why measure pronation-supination with the elbow flexed?","To prevent shoulder rotation from adding false range."]],
  refs:[{b:"levangie", ch:"The Elbow Complex"},{b:"neumann", ch:"Elbow and Forearm"},{b:"brunnstrom", ch:"Elbow and Forearm"}],
  keywords:["humeroulnar","humeroradial","radioulnar","annular ligament","interosseous membrane","pronation","supination"],
  mcq:[["The close-packed position of the humeroradial joint is",["Full extension with supination","90 degrees flexion with about 5 degrees supination","Full flexion with pronation","Full extension with pronation"],1,"The humeroradial joint is close-packed at about 90 degrees flexion and slight supination."],["Fibres of the interosseous membrane mostly run",["From ulna proximally to radius distally","Horizontally","From radius proximally to ulna distally","Vertically"],2,"This orientation lets load from the hand pass from the radius to the ulna."]]
},
{
  id:"bk-carrying-angle", title:"Carrying angle of the elbow and factors limiting elbow ROM", subject:"Kinesiology", region:"Elbow and forearm", stages:"steps",
  aliases:["carrying angle","cubitus valgus","cubitus varus","gunstock deformity","elbow end feel","elbow range limitation"],
  simple:"When the arm hangs straight with the palm forward, the forearm angles slightly away from the body; this is the carrying angle, normally about 10-15 degrees. Elbow range is stopped by bone meeting bone, soft tissue squeezing together and ligaments, capsule and muscles becoming tight. Knowing these limits helps us read end feel and plan stretching.",
  flow:["Trochlea projects lower than capitulum","Oblique joint axis angles the forearm outward","Normal valgus about 10-15 degrees, more in women","Flexion stops by soft tissue and bony contact","Extension stops by olecranon in its fossa","Pronation and supination stop by ligaments and muscles"],
  exam:[
    {h:"Definition of carrying angle", p:["Angle between the long axis of the arm and the long axis of the forearm in the frontal plane, with the elbow fully extended and forearm supinated.","Normal: about 10-15 degrees of valgus in adults; usually a few degrees greater in females; it disappears in full flexion and pronation."]},
    {h:"Causes of the carrying angle", p:["Medial lip of the trochlea projects more distally than the lateral lip, so the axis of flexion-extension is oblique.","Trochlear notch of ulna is angled relative to the ulnar shaft.","Functional significance: the forearm clears the hip when carrying objects; in flexion the hand comes to the mouth."]},
    {h:"Abnormal carrying angle", p:["Cubitus valgus (increased angle, more than about 15-20 degrees): non-union of lateral condyle fracture, Turner syndrome; may stretch the ulnar nerve causing tardy ulnar nerve palsy.","Cubitus varus (reduced or reversed, gunstock deformity): commonly after malunited supracondylar fracture in children.","Measurement: goniometer axis over the elbow in anterior view, arms along humerus and forearm midlines, elbow extended and supinated."]},
    {h:"Factors limiting flexion", p:["Active flexion: soft tissue apposition of forearm and arm muscles (soft end feel).","Passive flexion: coronoid process in coronoid fossa, radial head in radial fossa, tension of posterior capsule and triceps.","Normal range about 145 degrees active, slightly more passive."]},
    {h:"Factors limiting extension, pronation and supination", p:["Extension: olecranon process locking into olecranon fossa (hard bony end feel), anterior capsule, anterior fibres of MCL, tension in elbow flexors.","Pronation: crossing of radius over ulna, tension in supinator and biceps, distal radioulnar ligaments and interosseous membrane; firm end feel.","Supination: tension in pronator teres and quadratus, palmar distal radioulnar ligament, quadrate ligament and oblique cord; firm end feel."]},
    {h:"Physiotherapy relevance and conclusion", p:["Altered end feel (springy block, empty, early hard) signals loose body, effusion, myositis ossificans or heterotopic bone.","Stretch soft tissue limits gently and progressively (low-load prolonged stretch, 30 seconds to several minutes); never force a bony block.","Carrying angle and end feels are simple but high-yield; they link anatomy to safe mobilisation."]}
  ],
  tip:"Draw the arm and forearm in anatomical position with the forearm deviated laterally; mark the angle between the two long axes as about 10-15 degrees. Draw a second small sketch of cubitus varus as a gunstock shape for comparison.",
  evidence:[["Low-load prolonged stretch or static progressive splints for stiff elbow","Gains in range are commonly reported","Low"],["Aggressive forced passive stretching after trauma","Linked to heterotopic ossification risk; avoided","Expert opinion"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System",
  outcomes:[["Goniometric carrying angle","Valgus or varus alignment"],["End feel assessment","Nature of the limiting tissue"],["Elbow ROM","Flexion-extension and rotation arcs"]],
  recent:["Ultrasound-guided assessment and early motion protocols are increasingly used after elbow trauma to reduce stiffness while protecting healing structures."],
  mnemonic:{word:"BLMS", items:[["B","Bone: olecranon and coronoid in fossae"],["L","Ligaments and capsule"],["M","Muscles: antagonists on stretch"],["S","Soft tissue apposition"]], extra:"Carrying angle: arm and forearm, extended and supinated, about 10-15 degrees."},
  example:"A 9-year-old boy in Tirunelveli had a supracondylar fracture two years ago and now has a gunstock elbow. His carrying angle measures 5 degrees of varus compared with 12 degrees of valgus on the normal side.",
  flags:["Progressive ulnar paraesthesia with cubitus valgus: tardy ulnar nerve palsy","Early hard end feel after injury: heterotopic bone; avoid forced stretching","Sudden locking: loose body in the joint"],
  viva:[["Why does the carrying angle vanish in flexion?","Because the oblique trochlear axis brings the forearm in line with the arm as the elbow flexes."],["What is the end feel of normal elbow extension?","Hard (bone to bone) due to olecranon in its fossa."],["Gunstock deformity follows which fracture?","Malunited supracondylar fracture of the humerus."]],
  refs:[{b:"levangie", ch:"The Elbow Complex"},{b:"neumann", ch:"Elbow and Forearm"},{b:"brunnstrom", ch:"Elbow and Forearm"}],
  keywords:["carrying angle","cubitus valgus","cubitus varus","end feel","elbow range","trochlea"],
  mcq:[["The normal adult carrying angle is about",["0 degrees","10-15 degrees valgus","25-30 degrees valgus","10 degrees varus"],1,"The normal carrying angle is about 10-15 degrees, a little more in females."],["Tardy ulnar nerve palsy is associated with",["Cubitus varus","Cubitus valgus","Pulled elbow","Tennis elbow"],1,"An increased valgus angle stretches the ulnar nerve over years."]]
},
{
  id:"bk-wrist-joints", title:"Wrist complex: radiocarpal and midcarpal joints", subject:"Kinesiology", region:"Wrist and hand", stages:"steps",
  aliases:["wrist joint","radiocarpal joint","midcarpal joint","wrist kinematics","TFCC","proximal carpal row"],
  simple:"The wrist is two joints stacked: the radius meets the first row of carpal bones, and the first row meets the second row. Both share in bending, straightening and side-to-side motion. The ulna does not touch the carpals directly; a cartilage cushion called the TFCC sits in between.",
  flow:["Radius articulates with scaphoid and lunate","TFCC cushions ulnar side of wrist","Proximal row acts as an intercalated segment","Midcarpal joint adds motion between rows","Flexion and extension share both joints","Deviation moves proximal row in flexion or extension"],
  exam:[
    {h:"Introduction", p:["The wrist complex includes the radiocarpal and midcarpal joints; it is biaxial, giving flexion-extension and radial-ulnar deviation.","It adjusts length-tension of finger muscles and positions the hand for grip."]},
    {h:"Radiocarpal joint", p:["Ellipsoid (condyloid) synovial joint: concave distal radius and TFCC proximally; convex scaphoid, lunate and triquetrum distally.","Distal radius has an ulnar (radial) inclination of about 22-23 degrees and a palmar tilt of about 11-12 degrees, which explain greater ulnar deviation and flexion ranges.","TFCC (articular disc, ulnocarpal ligaments, meniscus homologue) stabilises the distal radioulnar joint and transmits about a fifth of axial load through the ulnar side."]},
    {h:"Midcarpal joint", p:["Between proximal row (scaphoid, lunate, triquetrum) and distal row (trapezium, trapezoid, capitate, hamate); functionally compound with medial and lateral parts.","Distal row is tightly bound to the metacarpals and moves as one unit with the hand.","Proximal row has no tendon attachments (intercalated segment) and is moved by forces from the bones around it; scaphoid bridges the two rows."]},
    {h:"Ligaments and kinematics", p:["Extrinsic ligaments: palmar radiocarpal (strong), dorsal radiocarpal, ulnocarpal, radial and ulnar collaterals; intrinsic: scapholunate and lunotriquetral interosseous ligaments.","Flexion-extension: both joints contribute; extension involves relatively more radiocarpal motion and flexion more midcarpal motion in classic descriptions.","Radial deviation: proximal row flexes; ulnar deviation: proximal row extends.","Range: flexion 65-85, extension 60-75, radial deviation 15-20, ulnar deviation 30-40 degrees; close-packed in full extension."]},
    {h:"Applied aspects", p:["Scaphoid fracture (risk of avascular necrosis of proximal pole), scapholunate dissociation leading to DISI (dorsal intercalated segment instability), lunotriquetral injury leading to VISI.","Colles fracture alters palmar tilt and radial inclination, reducing range and grip.","Physiotherapy: joint mobilisation (distraction and glides), tendon gliding, grip strengthening; functional range for daily tasks is about 40 degrees flexion and 40 degrees extension."]},
    {h:"Conclusion", p:["Wrist stability depends on ligaments and carpal geometry rather than muscle insertions on the proximal row; injury to carpal ligaments disturbs the whole linkage."]}
  ],
  tip:"Draw the distal radius, ulna with TFCC, and the two carpal rows as blocks. Label radiocarpal and midcarpal joint lines, then add the 22 degree radial inclination and 11 degree palmar tilt on small lateral and AP sketches.",
  evidence:[["Joint mobilisation after distal radius fracture","May add short-term gains in range and pain","Low"],["Early supervised exercise after Colles fracture","Improves early function versus advice alone in some trials","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System; Cochrane review on rehabilitation after distal radius fracture",
  outcomes:[["Goniometry of wrist","Flexion, extension and deviation"],["PRWE","Patient rated wrist pain and function"],["Grip dynamometry","Functional strength"]],
  recent:["Carpal kinematics are now studied with four-dimensional CT, refining older models of row and column theories."],
  mnemonic:{word:"Some Lovers Try Positions That They Can't Handle", items:[["Proximal","Scaphoid, Lunate, Triquetrum, Pisiform"],["Distal","Trapezium, Trapezoid, Capitate, Hamate"]], extra:"Proximal row has no tendon insertions except pisiform, a sesamoid in FCU."},
  example:"A 55-year-old woman in Trichy has stiffness after a healed Colles fracture. X-ray shows loss of palmar tilt, explaining her reduced wrist flexion; mobilisation and graded grip work start in the clinic.",
  flags:["Snuffbox tenderness after a fall: suspect scaphoid fracture even if first X-ray is normal","Numbness in median distribution after distal radius fracture: acute carpal tunnel","Disproportionate pain, swelling and colour change: complex regional pain syndrome"],
  viva:[["Which carpal bone has no tendon attachment and acts as intercalated segment?","The proximal row as a whole; for example the lunate has no tendon insertions."],["What does TFCC stand for?","Triangular fibrocartilage complex."],["Close-packed position of the wrist?","Full extension (with slight radial deviation in some texts)."]],
  refs:[{b:"levangie", ch:"The Wrist and Hand Complex"},{b:"neumann", ch:"Wrist"},{b:"brunnstrom", ch:"Wrist and Hand"}],
  keywords:["radiocarpal","midcarpal","TFCC","carpal kinematics","scaphoid","intercalated segment"],
  mcq:[["Normal palmar tilt of the distal radius is about",["0 degrees","11-12 degrees","22-23 degrees","35 degrees"],1,"Palmar (volar) tilt is about 11-12 degrees; radial inclination is about 22-23 degrees."],["During radial deviation the proximal carpal row",["Extends","Flexes","Does not move","Supinates"],1,"The proximal row flexes in radial deviation and extends in ulnar deviation."]]
},
{
  id:"bk-hand-joints", title:"CMC, MCP and IP joints of the fingers and thumb", subject:"Kinesiology", region:"Wrist and hand", stages:"steps",
  aliases:["carpometacarpal joint","metacarpophalangeal joint","interphalangeal joint","thumb CMC saddle joint","volar plate","collateral ligaments hand"],
  simple:"Each finger has joints at its base (CMC), knuckle (MCP) and two finger joints (PIP and DIP); the thumb has one fewer finger joint. The thumb base is a saddle that lets it swing across the palm to oppose. Collateral ligaments at the knuckles are tight when bent, which is why we splint knuckles bent and finger joints straight.",
  flow:["CMC joints shape the palmar arches","Thumb CMC saddle allows opposition","MCP joints are condyloid with volar plates","Collaterals tighten in MCP flexion by cam effect","IP joints are pure hinges","Splint MCP flexed and IP extended"],
  exam:[
    {h:"Introduction", p:["Hand joints form arches (proximal and distal transverse, longitudinal) that allow cupping and grip.","Thumb: CMC, MCP and IP; fingers: CMC, MCP, PIP and DIP."]},
    {h:"Carpometacarpal joints", p:["Fingers: plane joints; 2nd and 3rd are almost immobile (central pillar), 4th and 5th progressively mobile, deepening the palm during power grip.","Thumb CMC: saddle joint between trapezium and 1st metacarpal; 2 degrees of freedom (flexion-extension in the plane of the palm, abduction-adduction perpendicular to it) plus some axial rotation giving opposition.","Opposition = abduction + flexion + medial rotation of 1st metacarpal; reposition reverses it. Common site of osteoarthritis."]},
    {h:"Metacarpophalangeal joints", p:["Fingers: condyloid, biaxial (flexion-extension, abduction-adduction) with some passive rotation.","Volar (palmar) plate prevents hyperextension; deep transverse metacarpal ligament links plates.","Collateral ligaments are lax in extension and taut in flexion because the metacarpal head is cam-shaped; hence little abduction in flexion.","Range: flexion about 90 degrees (increasing from index to little finger), hyperextension variable; thumb MCP flexion about 50-60 degrees."]},
    {h:"Interphalangeal joints", p:["Hinge joints, 1 degree of freedom; volar plates and collateral ligaments similar to MCP.","PIP flexion 100-110 degrees, DIP 80-90 degrees; thumb IP about 80 degrees flexion with some hyperextension.","Check-rein ligaments at PIP limit hyperextension; their contracture causes flexion deformity."]},
    {h:"Applied aspects and splinting", p:["Safe position (intrinsic plus, position of protection): wrist 20-30 degrees extension, MCP 70-90 degrees flexion, IP full extension, thumb abducted; keeps collaterals and volar plates on stretch to prevent contracture.","Deformities: boutonniere, swan neck, mallet finger, ulnar drift in rheumatoid arthritis, thumb CMC OA (positive grind test).","Physiotherapy: tendon gliding, joint mobilisation, blocking exercises, splinting and joint protection."]},
    {h:"Conclusion", p:["Fine design of hand joints explains both their versatility and their tendency to stiffen; correct immobilisation position is a key exam and clinical point."]}
  ],
  tip:"Draw a lateral view of a finger with MCP, PIP and DIP; show the cam-shaped metacarpal head with the collateral ligament slack in extension and taut in flexion. Draw the thumb CMC as two interlocking saddles.",
  evidence:[["Splinting in safe position after hand injury","Standard practice to prevent collateral and volar plate contracture","Expert opinion"],["Exercise and splinting for thumb CMC OA","Reduce pain and improve function modestly","Moderate"]],
  evidenceSource:"Levangie and Norkin; Neumann, Kinesiology of the Musculoskeletal System; OARSI and EULAR recommendations on hand OA",
  outcomes:[["Total active motion","Finger joint mobility"],["Kapandji opposition score","Thumb opposition range"],["Pinch gauge","Pinch strength"]],
  recent:["EULAR recommendations for hand OA emphasise education, exercise and orthoses for thumb base OA before surgery."],
  mnemonic:{word:"FIX", items:[["F","Flex MCP"],["I","IP straight"],["X","eXtend the wrist slightly"]], extra:"Safe splint: MCP 70-90 flexed, IP 0, wrist 20-30 extended, thumb abducted."},
  example:"A 45-year-old cook in Vellore had a burn of the dorsum of the hand. The therapist splints the MCPs in 70 degrees flexion with IPs straight to prevent claw contracture.",
  flags:["Rotational malalignment of a finger after fracture: scissoring on flexion","Hot swollen MCP joints: inflammatory arthritis flare","Splinting MCP in extension for weeks: collateral ligament contracture"],
  viva:[["Why are MCP collaterals tight in flexion?","The metacarpal head is cam-shaped and wider palmarly, so ligaments stretch as the joint flexes."],["What type of joint is the thumb CMC?","Saddle (sellar) joint."],["Which CMC joints are least mobile?","Second and third."]],
  refs:[{b:"levangie", ch:"The Wrist and Hand Complex"},{b:"neumann", ch:"Hand"},{b:"brunnstrom", ch:"Wrist and Hand"}],
  keywords:["CMC","MCP","IP","volar plate","opposition","safe position"],
  mcq:[["In the position of safe immobilisation the MCP joints are kept in",["Full extension","70-90 degrees flexion","30 degrees hyperextension","Full abduction"],1,"MCP flexion keeps the collateral ligaments stretched to prevent contracture."],["Opposition of the thumb occurs mainly at the",["IP joint","MCP joint","CMC joint","Radiocarpal joint"],2,"The saddle-shaped thumb CMC joint provides the abduction, flexion and rotation of opposition."]]
},
{
  id:"bk-thumb-intrinsic-muscles", title:"Extrinsic and intrinsic thumb muscles; interossei and lumbricals", subject:"Kinesiology", region:"Wrist and hand", stages:"steps",
  aliases:["thenar muscles","adductor pollicis","interossei","lumbricals","extensor mechanism","intrinsic minus hand","claw hand"],
  simple:"The thumb is moved by long muscles from the forearm (extrinsics) and short muscles in the hand (intrinsics). Small interossei and lumbricals in the palm bend the knuckles while straightening the finger joints through the extensor hood. Losing these small muscles gives a claw hand.",
  flow:["Extrinsic thumb muscles give strong long-range motion","Thenar muscles position the thumb for opposition","Adductor pollicis powers key pinch","Interossei abduct and adduct fingers","Lumbricals link flexor and extensor tendons","Intrinsics flex MCP and extend IP joints"],
  exam:[
    {h:"Extrinsic thumb muscles", p:["Abductor pollicis longus and extensor pollicis brevis: radial abduction and MCP extension; their tendons pass in the first dorsal compartment (De Quervain tenosynovitis).","Extensor pollicis longus: extends IP joint, forms ulnar border of anatomical snuffbox, can rupture after Colles fracture.","Flexor pollicis longus (anterior interosseous branch of median nerve): flexes IP joint; tested by tip pinch.","Radial nerve supplies APL, EPB, EPL."]},
    {h:"Intrinsic thumb muscles", p:["Thenar group: abductor pollicis brevis, flexor pollicis brevis (superficial head median, deep head ulnar), opponens pollicis; recurrent branch of median nerve.","Adductor pollicis (deep branch of ulnar nerve): powerful adduction for key pinch; weakness gives Froment sign (IP flexion by FPL substitution).","First dorsal interosseous stabilises index against thumb pressure."]},
    {h:"Interossei", p:["Palmar interossei (usually 4 including thumb part, or 3): adduct fingers towards the axis of the middle finger (PAD).","Dorsal interossei (4): abduct away from the middle finger axis (DAB); bipennate.","All supplied by deep branch of ulnar nerve; both groups flex MCP and extend IP through the extensor hood (lateral bands)."]},
    {h:"Lumbricals", p:["Four; arise from FDP tendons in the palm and insert into the radial side of the extensor expansion.","First and second: median nerve; third and fourth: ulnar nerve.","Action: flex MCP and extend PIP and DIP; by pulling FDP distally they reduce flexor tension, aiding fast finger extension; rich in proprioceptors."]},
    {h:"Applied: extensor mechanism and claw hand", p:["Extensor expansion: central slip to middle phalanx, lateral bands (with intrinsic contributions) to distal phalanx, retinacular ligaments coordinate PIP and DIP.","Intrinsic minus (claw) hand in ulnar nerve palsy: MCP hyperextension and IP flexion, most marked in ring and little fingers; worse in low lesion (ulnar paradox).","Intrinsic plus position: MCP flexion with IP extension.","Physiotherapy: anti-claw (knuckle bender) splint, intrinsic strengthening with putty and finger abduction bands, sensory re-education, tendon transfer rehabilitation."]},
    {h:"Conclusion", p:["Fine and strong thumb use and balanced finger movement depend on intact intrinsics; nerve palsies reveal their role clearly."]}
  ],
  tip:"Draw a dorsal view of one finger with the extensor expansion: central slip, two lateral bands and the lumbrical joining on the radial side. Add a small palm sketch showing PAD (palmar adduct) and DAB (dorsal abduct) arrows around the middle finger axis.",
  evidence:[["Tendon transfer for ulnar claw hand with structured rehab","Improves hand function in leprosy and nerve injury cohorts","Low"],["Anti-claw splinting","Prevents contracture and improves function","Expert opinion"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin; B D Chaurasia, Human Anatomy Vol 1",
  outcomes:[["Card test and Froment sign","Interossei and adductor pollicis power"],["Pinch gauge","Key and tip pinch strength"],["Manual muscle testing","Thenar and intrinsic grades"]],
  recent:["Leprosy remains an important cause of ulnar and median claw hand in India, where reconstructive surgery and physiotherapy programmes continue under national programmes."],
  mnemonic:{word:"PAD DAB", items:[["PAD","Palmar interossei ADduct"],["DAB","Dorsal interossei ABduct"]], extra:"Lumbricals 1 and 2 by median, 3 and 4 by ulnar: same split as FDP."},
  example:"A 28-year-old man from Kanchipuram with leprosy shows clawing of the ring and little fingers and a positive Froment sign. He uses a knuckle-bender splint while awaiting tendon transfer.",
  flags:["Painless clawing with thickened nerves: screen for leprosy","Sudden loss of thumb IP extension after wrist fracture: EPL rupture","Wasting of first dorsal interosseous: ulnar nerve or C8-T1 lesion"],
  viva:[["What is Froment sign?","Flexion of the thumb IP joint by FPL during key pinch because adductor pollicis is weak (ulnar palsy)."],["Origin of lumbricals?","From the tendons of flexor digitorum profundus."],["What is the ulnar paradox?","Clawing is worse in a low ulnar lesion because FDP to ring and little fingers is spared and flexes the IPs."]],
  refs:[{b:"neumann", ch:"Hand"},{b:"levangie", ch:"The Wrist and Hand Complex"},{b:"brunnstrom", ch:"Wrist and Hand"},{c:"Chaurasia BD. Human Anatomy, Volume 1: Upper Limb and Thorax. Chapter: Hand."}],
  keywords:["thenar","adductor pollicis","interossei","lumbricals","claw hand","extensor expansion"],
  mcq:[["Dorsal interossei of the hand",["Adduct the fingers","Abduct the fingers","Extend the MCP joints","Oppose the thumb"],1,"Dorsal interossei abduct (DAB) and palmar interossei adduct (PAD)."],["Lumbricals arise from",["Flexor digitorum superficialis tendons","Metacarpal shafts","Flexor digitorum profundus tendons","Flexor retinaculum"],2,"They arise from FDP tendons, which is unique among muscles."]]
},
{
  id:"bk-prehension-grips", title:"Prehension: power grip, cylindrical, spherical and hook grips", subject:"Kinesiology", region:"Wrist and hand", stages:"steps",
  aliases:["prehension","power grip","cylindrical grip","spherical grip","hook grip","Napier grip classification","grip strength"],
  simple:"Prehension means using the hand to hold or grasp. Power grips use the whole hand and palm to hold firmly, like holding a hammer, a ball or a bag. Each grip uses a different mix of finger flexors, thumb and small hand muscles.",
  flow:["Object size and task decide grip type","Fingers flex around the object","Palm contacts object in power grips","Thumb wraps or stabilises","Wrist extends and deviates ulnarly for strength","Ulnar fingers give most power"],
  exam:[
    {h:"Definition and classification", p:["Prehension: the act of grasping or holding an object between parts of the hand.","Napier classified grips into power grip (force, whole hand) and precision handling (fine control with finger pads and thumb).","Power grips: cylindrical, spherical, hook and lateral (lateral prehension between fingers, some texts); precision: pad-to-pad, tip-to-tip, pad-to-side."]},
    {h:"Cylindrical grip", p:["Object held against the palm with fingers flexed around it and thumb adducted around the other side (for example holding a hammer, rod, cricket bat handle).","Muscles: FDP and FDS (FDS more as force increases), interossei for MCP flexion, thenar muscles and adductor pollicis; wrist in slight extension and ulnar deviation for optimum finger flexor length.","Ring and little fingers flex more and contribute much of the force; 4th and 5th CMC mobility deepens the palm."]},
    {h:"Spherical grip", p:["Fingers spread and flexed around a round object (ball, apple, door knob) with the palm cupped.","Interossei abduct fingers; hypothenar and thenar muscles cup the palm; MCP collaterals must allow abduction during flexion.","Wrist in slight extension; thumb opposed."]},
    {h:"Hook grip", p:["Fingers flexed at IP joints (and variably at MCP) forming a hook; thumb is not used (carrying a bucket or shopping bag, hanging from a bar).","Muscles: FDP and FDS mainly; can be performed even with median-ulnar intrinsic loss if long flexors work.","Useful grip for patients with thumb loss."]},
    {h:"Assessment and physiotherapy", p:["Grip strength with Jamar dynamometer, handle position 2, elbow at 90 degrees, average of 3 trials; compare sides.","Training: putty, grip trainers, functional tasks with graded cylinders and balls, wrist extensor strengthening (tenodesis principle).","Adaptive equipment: built-up handles for weak grip in RA, stroke and SCI; tenodesis grip training in C6 tetraplegia."]},
    {h:"Conclusion", p:["Power grips depend on long flexors, intrinsic balance and a stable extended wrist; grip type should match the patient's daily activities when planning rehab."]}
  ],
  tip:"Draw four small hand sketches side by side labelled cylindrical (rod), spherical (ball), hook (bag handle) and lateral or key pinch. Add arrows showing wrist slight extension and ulnar deviation in the cylindrical sketch.",
  evidence:[["Grip strength as a health marker","Low grip strength is associated with poorer outcomes in older adults","Moderate"],["Task-specific grip training after stroke","Improves hand function when practice dose is high","Moderate"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin; Napier JR, The prehensile movements of the human hand (J Bone Joint Surg Br, 1956)",
  outcomes:[["Jamar dynamometer","Power grip strength"],["Jebsen-Taylor Hand Function Test","Timed hand function"],["Box and Block test","Gross manual dexterity"]],
  recent:["Grip strength is widely used as a vital sign of overall muscle function and is included in sarcopenia definitions such as the Asian Working Group for Sarcopenia criteria."],
  mnemonic:{word:"CHS", items:[["C","Cylinder: hammer"],["H","Hook: bag, no thumb"],["S","Sphere: ball, fingers spread"]], extra:"Power grips use the palm; precision grips do not."},
  example:"A 62-year-old farmer in Thanjavur with rheumatoid arthritis struggles to hold a sickle. The therapist builds up the handle and trains cylindrical grip with joint protection.",
  flags:["Sudden loss of grip with neck pain: cervical myelopathy or radiculopathy","Excessive grip training in active RA can worsen ulnar drift","Grip pain at the base of thumb: CMC OA or De Quervain"],
  viva:[["Who classified grips into power and precision?","John Napier."],["Which grip does not use the thumb?","Hook grip."],["Ideal wrist position for strongest grip?","Slight extension (about 20-30 degrees) with slight ulnar deviation."]],
  refs:[{b:"neumann", ch:"Hand"},{b:"levangie", ch:"The Wrist and Hand Complex"},{b:"brunnstrom", ch:"Wrist and Hand"}],
  keywords:["prehension","power grip","cylindrical","spherical","hook","grip strength"],
  mcq:[["Carrying a bucket by its handle uses which grip?",["Spherical","Tip-to-tip","Hook","Lateral pinch"],2,"Hook grip uses the flexed fingers without the thumb."],["Grip strength is greatest with the wrist in",["Full flexion","Slight extension and ulnar deviation","Full radial deviation","Full extension and radial deviation"],1,"Slight extension keeps the finger flexors at an effective length."]]
},
{
  id:"bk-precision-handling", title:"Precision handling and functional position of the wrist and hand", subject:"Kinesiology", region:"Wrist and hand", stages:"steps",
  aliases:["precision grip","pinch types","tip to tip pinch","pad to pad pinch","key pinch","functional position of hand","position of function"],
  simple:"Precision handling is holding and moving small objects with the thumb and finger pads, like writing or threading a needle. The functional position is the relaxed ready posture of wrist and hand from which grips are easiest. Keeping a hand in this position after injury helps it stay useful.",
  flow:["Thumb opposes to finger pad or tip","Intrinsics control fine finger movement","Long flexors adjust pressure","Sensation guides force and slip","Wrist slight extension keeps tendons balanced","Functional position prepares hand for grasp"],
  exam:[
    {h:"Definition", p:["Precision handling: manipulation of objects between the thumb and fingers without palmar contact, where control matters more than force.","Functional position: the position of the wrist and hand from which grasp is most efficiently performed."]},
    {h:"Types of precision handling", p:["Pad-to-pad (palmar pinch): thumb pad to index or index and middle pads; most common (holding a pen, coin). Three-jaw chuck when two fingers are used.","Tip-to-tip: tip of thumb to tip of index; picking a pin or thread; needs FDP, FPL and full IP flexion.","Pad-to-side (lateral or key pinch): thumb pad against radial side of index middle phalanx; strongest pinch, uses adductor pollicis and first dorsal interosseous."]},
    {h:"Muscles and control", p:["Thumb: opponens, APB, FPB position the thumb; FPL flexes IP for tip pinch; adductor pollicis gives force in key pinch.","Fingers: FDP for tip, FDS for pad, interossei and lumbricals fine-tune MCP and IP position.","Intact sensation (median nerve) is essential; in median palsy precision is lost even with good motor power."]},
    {h:"Functional position of wrist and hand", p:["Wrist about 20-30 degrees extension with slight ulnar deviation (about 10 degrees).","MCP about 45 degrees flexion, PIP about 30-45 degrees, DIP slight flexion (about 10-20 degrees).","Thumb abducted and partly opposed, in line with the radius, pad facing the index pad.","Differs from the safe immobilisation position (MCP 70-90 flexion with IP extension), which is used to prevent ligament contracture."]},
    {h:"Assessment and physiotherapy", p:["Pinch gauge for tip, key and palmar pinch; Nine Hole Peg Test, Purdue Pegboard for dexterity.","Training: picking beans, coins and beads, buttoning, writing with thick pen, therapeutic putty pinching; sensory re-education after nerve repair.","Splinting in functional position when long-term stiffness is expected, so the hand remains usable even if it stiffens."]},
    {h:"Conclusion", p:["Precision handling needs thumb opposition, intrinsic control and sensation; the functional position keeps the wrist and hand ready for both power and precision use."]}
  ],
  tip:"Draw a side view of a hand in functional position, marking wrist 20-30 degrees extension, MCP 45, PIP 30 and the thumb opposed to the index. Add three small inset sketches for tip, pad and key pinch.",
  evidence:[["Sensory re-education after median nerve repair","May improve tactile discrimination and function","Low"],["Fine motor task practice after stroke","Improves dexterity when practised intensively","Moderate"]],
  evidenceSource:"Levangie and Norkin; Neumann, Kinesiology of the Musculoskeletal System; Brunnstrom's Clinical Kinesiology",
  outcomes:[["Pinch gauge","Tip, key and palmar pinch strength"],["Nine Hole Peg Test","Finger dexterity"],["Two-point discrimination","Fingertip sensation for precision"]],
  recent:["Digital tools such as tablet tracing and sensor gloves are being studied to measure fine motor control objectively in neurological rehabilitation."],
  mnemonic:{word:"TPK", items:[["T","Tip: pin, FDP and FPL"],["P","Pad: pen, most common"],["K","Key: lateral, strongest"]], extra:"Functional position: wrist 20-30 extension, MCP 45, PIP 30, thumb opposed."},
  example:"A 35-year-old tailor in Tiruppur cannot thread a needle after a median nerve repair at the wrist. Therapy includes tip pinch practice with beads and sensory re-education.",
  flags:["Sudden loss of tip pinch (no IP flexion of thumb and index): anterior interosseous nerve palsy","Loss of pad sensation with burns: protect the hand","Splinting in wrong position can cause permanent loss of function"],
  viva:[["Which is the strongest pinch?","Lateral (key) pinch."],["What is the functional position of the wrist?","About 20-30 degrees extension with slight ulnar deviation."],["Which nerve lesion abolishes the OK sign?","Anterior interosseous nerve (FPL and index FDP)."]],
  refs:[{b:"levangie", ch:"The Wrist and Hand Complex"},{b:"neumann", ch:"Hand"},{b:"brunnstrom", ch:"Wrist and Hand"}],
  keywords:["precision handling","pinch","tip to tip","key pinch","functional position","dexterity"],
  mcq:[["Threading a needle mainly uses",["Hook grip","Tip-to-tip pinch","Cylindrical grip","Spherical grip"],1,"Tip-to-tip pinch is the finest precision handling."],["In the functional position of the hand the wrist is in",["40 degrees flexion","Neutral with radial deviation","20-30 degrees extension","Full extension"],2,"The wrist rests in slight extension so finger flexors work efficiently."]]
},
{
  id:"bk-hip-joint-structure", title:"Hip joint: structure, angle of inclination and angle of torsion", subject:"Kinesiology", region:"Hip", stages:"steps",
  aliases:["hip joint biomechanics","angle of inclination","neck shaft angle","angle of torsion","femoral anteversion angle","centre edge angle","iliofemoral ligament"],
  simple:"The hip is a deep ball and socket joint built for stability while carrying body weight. The femoral neck meets the shaft at about 125 degrees (angle of inclination) and is twisted forward about 15 degrees (angle of torsion). These angles decide how well the head sits in the socket and how hard the hip muscles must work.",
  flow:["Acetabulum faces lateral, anterior and inferior","Labrum deepens socket and seals the joint","Femoral neck angles 125 degrees to shaft","Neck twisted forward about 15 degrees","Spiral ligaments tighten in extension","Trabeculae carry weight from head to shaft"],
  exam:[
    {h:"Introduction", p:["Synovial ball and socket joint with 3 degrees of freedom; primary role is weight bearing and stability, with good mobility.","Acetabulum (ilium, ischium, pubis meet at triradiate cartilage) faces laterally, anteriorly and inferiorly; lunate surface is the articular part."]},
    {h:"Articular surfaces and ligaments", p:["Acetabular labrum deepens the socket, maintains a suction seal; transverse acetabular ligament completes the rim; ligamentum teres carries a small artery.","Centre-edge angle of Wiberg (acetabular coverage) about 30-40 degrees in adults; reduced in dysplasia.","Capsular ligaments: iliofemoral (Y ligament of Bigelow, strongest), pubofemoral, ischiofemoral; all spiral and become taut in extension, allowing upright standing with little muscle work. Zona orbicularis encircles the neck.","Close-packed: full extension with slight abduction and medial rotation."]},
    {h:"Angle of inclination (neck-shaft angle)", p:["Angle between the axis of the femoral neck and the axis of the shaft in the frontal plane.","About 150 degrees at birth, about 125 degrees in adults, decreasing to about 120 degrees in elderly.","Larger in coxa valga (more than about 135-140 degrees) and smaller in coxa vara (less than about 120 degrees).","It offsets the shaft from the pelvis, gives abductors a lever arm and allows wide range without impingement."]},
    {h:"Angle of torsion (anteversion)", p:["Angle between the axis of the femoral neck and the transcondylar axis of the femoral condyles in the transverse plane.","About 30-40 degrees at birth, about 10-15 degrees in adults; reduces with growth and weight bearing.","Increased: anteversion (in-toeing); decreased or reversed: retroversion (out-toeing). Measured clinically by Craig test."]},
    {h:"Trabecular system and range", p:["Medial (compressive) trabecular system from shaft medial cortex to head; lateral (tensile) system arches from lateral cortex to inferior head; Ward triangle is a weak zone prone to fracture in osteoporosis.","Range: flexion about 120 degrees (knee flexed), extension 10-20, abduction 40-45, adduction 20-30, medial rotation 35-45, lateral rotation 45 degrees.","Joint reaction force can reach about 2.5-3 times body weight in single limb stance and more in running."]},
    {h:"Applied aspects and conclusion", p:["Femoral neck fracture (elderly osteoporotic), DDH, Perthes disease, SCFE, femoroacetabular impingement and labral tears, hip OA.","Physiotherapy: abductor strengthening, protection of joint after arthroplasty (avoid flexion beyond 90 degrees with adduction and medial rotation after posterior approach), gait training.","Hip angles and ligaments explain its stability, common deformities and why abductor strength is central to rehab."]}
  ],
  tip:"Draw the proximal femur in AP view with lines along neck and shaft marking 125 degrees. Then draw a view from above showing the neck axis and the condylar axis with a 15 degree angle of torsion. Shade the medial and lateral trabecular systems and Ward triangle.",
  evidence:[["Hip abductor and extensor strengthening in hip OA","Reduces pain and improves function","High"],["Precautions after posterior approach THR","Traditional; some evidence that strict precautions may not reduce dislocation in all patients","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System; NICE guidance on osteoarthritis",
  outcomes:[["Goniometry","Hip range in all planes"],["Harris Hip Score","Hip function after surgery"],["Craig test","Clinical femoral anteversion"]],
  recent:["Hip arthroscopy for femoroacetabular impingement and labral tears has grown, with structured physiotherapy before and after surgery."],
  mnemonic:{word:"125-15", items:[["125","Adult angle of inclination in degrees"],["15","Adult angle of torsion (anteversion) in degrees"]], extra:"Babies start higher: about 150 inclination and 30-40 anteversion."},
  example:"A 70-year-old woman in Chennai falls in the bathroom and fractures her femoral neck through the weak Ward triangle region. After hemiarthroplasty, abductor strengthening and gait training begin early.",
  flags:["Groin pain and inability to bear weight after a fall in elderly: neck of femur fracture","Hip pain in a child with limp: Perthes, SCFE or septic arthritis","Hip flexion beyond 90 with adduction and IR after posterior THR: dislocation risk"],
  viva:[["Normal adult neck-shaft angle?","About 125 degrees."],["Strongest ligament of the hip?","Iliofemoral ligament (Y ligament of Bigelow)."],["Close-packed position of the hip?","Full extension with slight abduction and medial rotation."]],
  refs:[{b:"levangie", ch:"The Hip Complex"},{b:"neumann", ch:"Hip"},{b:"brunnstrom", ch:"Pelvis and Hip"}],
  keywords:["hip joint","angle of inclination","angle of torsion","anteversion","iliofemoral ligament","trabeculae"],
  mcq:[["The normal adult angle of torsion of the femur is about",["0 degrees","10-15 degrees","30-40 degrees","125 degrees"],1,"Adult anteversion is about 10-15 degrees; at birth it is about 30-40."],["Which hip ligament is strongest?",["Pubofemoral","Ischiofemoral","Ligamentum teres","Iliofemoral"],3,"The iliofemoral ligament is the strongest and limits hip extension."]]
},
{
  id:"bk-pelvic-tilt-lumbopelvic", title:"Pelvic tilts and lumbopelvic rhythm", subject:"Kinesiology", region:"Hip and pelvis", stages:"steps",
  aliases:["anterior pelvic tilt","posterior pelvic tilt","lateral pelvic tilt","pelvic rotation","lumbopelvic rhythm","forward bending mechanics"],
  simple:"The pelvis can tip forward, backward, sideways or rotate, and every movement of the pelvis changes the curve of the lower back and the angle at the hips. When you bend forward to touch your toes, the lumbar spine and the hips share the work in a pattern called lumbopelvic rhythm. Tight hamstrings or a stiff back upset this sharing.",
  flow:["Pelvis moves on femoral heads at the hips","Anterior tilt increases lumbar lordosis","Posterior tilt flattens the lumbar spine","Lateral tilt drops or hikes one side","Forward bending combines lumbar flexion and hip flexion","Return reverses pelvis first, then lumbar spine"],
  exam:[
    {h:"Introduction", p:["Pelvic motions occur at both hip joints (pelvis moving on femurs) and are linked to lumbar spine motion; neutral pelvis has ASIS and pubic symphysis in the same vertical plane and ASIS roughly level with PSIS or slightly lower.","Pelvic tilt is named by the direction the ASIS moves."]},
    {h:"Anterior and posterior pelvic tilt (sagittal plane)", p:["Anterior tilt: ASIS moves forward and down; produces hip flexion and increased lumbar lordosis. Force couple: hip flexors (iliopsoas, rectus femoris) and lumbar erector spinae.","Posterior tilt: ASIS moves backward and up; produces hip extension and lumbar flattening. Force couple: rectus abdominis and obliques with gluteus maximus and hamstrings.","Clinical: tight hip flexors and weak abdominals cause excessive anterior tilt (lower crossed syndrome); tight hamstrings cause posterior tilt and flat back."]},
    {h:"Lateral tilt and rotation", p:["Lateral pelvic tilt (frontal plane): in single limb stance the opposite side drops slightly (hip adduction of stance limb), controlled by stance side gluteus medius and minimus; excessive drop is the Trendelenburg sign.","Hip hiking: elevation of the opposite pelvis by quadratus lumborum, used to clear a stiff limb in swing.","Pelvic rotation (transverse plane): forward rotation of one side with the swinging limb, about 4 degrees each way in normal gait; increases step length."]},
    {h:"Lumbopelvic rhythm", p:["Coordinated movement of lumbar spine and pelvis (hips) during forward bending and return.","Forward bending: early phase mostly lumbar flexion, later phase mostly anterior pelvic tilt at the hips; typical total about 40-60 degrees lumbar flexion and about 60-70 degrees hip flexion, varying between people.","Return to upright: pelvis rotates posteriorly first (hip extensors), then lumbar spine extends, reducing load on lumbar tissues.","Some studies show both components overlap through the range rather than strictly in sequence."]},
    {h:"Clinical relevance and physiotherapy", p:["Tight hamstrings shift motion to lumbar spine, increasing disc stress; stiff lumbar spine shifts motion to hips.","Assessment: observe toe touch, modified Schober test, sit and reach, Thomas test, straight leg raise.","Management: pelvic tilt exercises (supine posterior tilt, 10 repetitions with 5-10 second holds), hamstring and hip flexor stretching (30 seconds, 3-4 repetitions), core and gluteal strengthening, hip hinge training for lifting."]},
    {h:"Conclusion", p:["Pelvic tilts link hip and lumbar posture; a balanced lumbopelvic rhythm protects the back during bending and lifting."]}
  ],
  tip:"Draw a side view of pelvis and lumbar spine three times: neutral, anterior tilt (increased lordosis) and posterior tilt (flat lumbar). Add arrows for each force couple. Then draw a forward bending figure with two arcs labelled lumbar flexion and hip flexion.",
  evidence:[["Motor control and core exercise for chronic low back pain","Similar benefit to other active exercise","Moderate"],["Hamstring stretching to change lumbopelvic rhythm","Changes flexibility; effect on back pain uncertain","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System; Cochrane reviews of exercise for low back pain",
  outcomes:[["Modified Schober test","Lumbar flexion range"],["Thomas test","Hip flexor length"],["Inclinometry","Pelvic and lumbar contributions to bending"]],
  recent:["Inertial sensors and smartphone inclinometers are being validated to measure lumbopelvic rhythm outside the laboratory."],
  mnemonic:{word:"FAB", items:[["F","Flexors plus back extensors"],["A","Anterior tilt"],["B","aBdominals plus glutes and hamstrings give posterior tilt"]], extra:"Bend: lumbar first then hips; return: hips first then lumbar."},
  example:"A 26-year-old software engineer in Bengaluru with low back pain bends forward mostly from his lumbar spine because his hamstrings are tight. Hamstring stretching and hip hinge training redistribute the movement.",
  flags:["Back pain with bladder or saddle changes: cauda equina","Marked pelvic obliquity in a child: check leg length and scoliosis","Painful restricted forward bending with night pain: rule out serious pathology"],
  viva:[["Which muscles produce posterior pelvic tilt?","Abdominals with gluteus maximus and hamstrings."],["What is lumbopelvic rhythm?","The coordinated contribution of lumbar flexion and hip flexion during forward bending and return."],["What controls lateral pelvic tilt in single limb stance?","Gluteus medius and minimus of the stance side."]],
  refs:[{b:"levangie", ch:"The Hip Complex"},{b:"neumann", ch:"Hip"},{b:"brunnstrom", ch:"Pelvis and Hip"}],
  keywords:["pelvic tilt","lumbopelvic rhythm","lordosis","force couple","Trendelenburg","forward bending"],
  mcq:[["Anterior pelvic tilt is associated with",["Lumbar flattening","Increased lumbar lordosis","Hip extension","Knee flexion"],1,"Anterior tilt increases lumbar lordosis and flexes the hips."],["While returning to upright from forward bending, the first component is usually",["Lumbar extension","Posterior pelvic tilt at the hips","Cervical extension","Knee extension"],1,"The pelvis rotates back first, then the lumbar spine extends."]]
},
{
  id:"bk-coxa-vara-valga", title:"Coxa vara, coxa valga, femoral anteversion and retroversion", subject:"Kinesiology", region:"Hip", stages:"011234",
  aliases:["coxa vara","coxa valga","femoral anteversion","femoral retroversion","in-toeing","out-toeing","Craig test"],
  simple:"If the femoral neck angle is smaller than normal it is coxa vara; if larger it is coxa valga. If the neck twists forward too much it is anteversion and the child walks with toes turned in; if too little or backward it is retroversion and the toes turn out. These shapes change muscle leverage, joint stress and gait.",
  flow:["Congenital, developmental or acquired bone change","Neck-shaft or torsion angle moves from normal","Lever arms and joint loading change","Limb length, rotation and gait alter","Measure with X-ray, CT and Craig test","Treat with exercise, gait training, sometimes osteotomy"],
  exam:[
    {h:"Definitions and normal values", p:["Angle of inclination normally about 125 degrees in adults; coxa vara is less than about 120 degrees; coxa valga is more than about 135-140 degrees.","Angle of torsion normally about 10-15 degrees anteversion in adults; excessive anteversion is above about 20-25 degrees; retroversion is torsion less than normal or directed backward."]},
    {h:"Causes", p:["Coxa vara: congenital or developmental coxa vara, SCFE, Perthes disease, malunited intertrochanteric fracture, rickets, osteomalacia, Paget disease, fibrous dysplasia.","Coxa valga: neuromuscular conditions with poor weight bearing and weak abductors (cerebral palsy, polio, DMD), DDH, juvenile arthritis.","Excess anteversion: persistence of infant anteversion, cerebral palsy, DDH; retroversion: SCFE, some developmental cases."]},
    {h:"Biomechanical effects", p:["Coxa vara: longer abductor lever arm (less abductor force needed), but increased bending and shear stress on the neck (risk of fracture or non-union), shortening of the limb, greater trochanter rises and abductors become slack, giving a Trendelenburg gait.","Coxa valga: shorter abductor lever arm so abductors work harder, higher joint reaction force, lengthened limb, head less covered and prone to lateral subluxation.","Anteversion: in-toeing gait, increased medial rotation and reduced lateral rotation, W-sitting, may increase Q angle and patellofemoral stress, compensatory external tibial torsion.","Retroversion: out-toeing, increased lateral rotation, reduced medial rotation, associated with femoroacetabular impingement and SCFE."]},
    {h:"Assessment", p:["X-ray AP pelvis for neck-shaft angle; CT or MRI for torsion.","Craig test (trochanteric prominence angle test): prone, knee 90 degrees, rotate hip until greater trochanter most prominent laterally; angle of leg from vertical estimates anteversion.","Hip rotation range in prone (medial rotation more than 70 degrees suggests excess anteversion), leg length, Trendelenburg test, foot progression angle during gait."]},
    {h:"Physiotherapy management", p:["Most childhood anteversion improves with growth; reassure, avoid prolonged W-sitting, encourage cross-legged sitting and active play.","Strengthen hip abductors and lateral rotators (side-lying abduction, clams, bridges, 2-3 sets of 10-15), gait training, shoe raise for shortening.","After corrective osteotomy (valgus osteotomy for coxa vara, varus derotation osteotomy in CP): protected weight bearing as advised, ROM and strengthening, gait re-education."]},
    {h:"Complications and conclusion", p:["Untreated deformity can lead to early OA, neck fracture, subluxation or patellofemoral pain.","Normal angles are 125 and 15 degrees; deviations explain many gait patterns seen in children and adults."]}
  ],
  tip:"Draw three proximal femurs side by side: coxa vara (angle about 100), normal (125) and coxa valga (150). Below, draw top views showing anteversion (neck forward of condylar axis) and retroversion. Label the abductor lever arm on the vara and valga drawings.",
  evidence:[["Natural history of childhood femoral anteversion","Most cases improve with growth without treatment","Moderate"],["Varus derotation osteotomy in cerebral palsy hip displacement","Improves hip containment; needs rehab","Low"]],
  evidenceSource:"Levangie and Norkin; Neumann, Kinesiology of the Musculoskeletal System; Staheli, studies on rotational problems in children",
  outcomes:[["Craig test","Femoral anteversion estimate"],["Foot progression angle","In-toeing or out-toeing"],["Trendelenburg test","Abductor efficiency"],["Leg length measurement","Shortening from vara"]],
  recent:["Hip surveillance programmes for cerebral palsy using regular pelvic X-rays help detect hip displacement and coxa valga early."],
  mnemonic:{word:"VALley and VALue", items:[["Vara","Valley: neck dips, angle smaller, limb shorter"],["Valga","Value goes up: angle bigger, limb longer"]], extra:"Anteversion in-toes, retroversion out-toes."},
  example:"A 6-year-old girl in Madurai sits in W position and trips while running. Craig test shows about 35 degrees anteversion; parents are reassured and she starts cross-legged sitting and hip lateral rotator play exercises.",
  flags:["Painful limp in obese adolescent with knee pain: SCFE until proved otherwise","Progressive coxa vara in a child: check for metabolic bone disease","Hip migration in cerebral palsy: risk of painful dislocation"],
  viva:[["What is coxa vara?","Reduced femoral neck-shaft angle, less than about 120 degrees."],["Name the clinical test for femoral anteversion.","Craig test, the trochanteric prominence angle test."],["Effect of coxa valga on hip abductors?","Shorter lever arm, so abductors must produce more force, raising joint load."]],
  refs:[{b:"levangie", ch:"The Hip Complex"},{b:"neumann", ch:"Hip"},{b:"brunnstrom", ch:"Pelvis and Hip"}],
  keywords:["coxa vara","coxa valga","anteversion","retroversion","Craig test","in-toeing"],
  mcq:[["Excessive femoral anteversion usually causes",["Out-toeing","In-toeing","Genu varum only","Increased lateral rotation"],1,"Anteversion turns the limb inward; patients show more medial rotation and in-toeing."],["In coxa vara the abductor lever arm",["Becomes longer, but neck bending stress increases","Becomes shorter","Is unchanged","Disappears"],0,"A smaller angle lengthens the lever arm but increases shear stress on the neck."]]
},
{
  id:"bk-tibiofemoral-joint", title:"Tibiofemoral joint: menisci, ligaments and axes", subject:"Kinesiology", region:"Knee", stages:"steps",
  aliases:["knee joint biomechanics","menisci function","cruciate ligaments","collateral ligaments knee","mechanical axis","anatomical axis","tibiofemoral angle"],
  simple:"The knee joint is where the rounded femur rests on the nearly flat tibia, so it depends on menisci and ligaments for stability. The two C-shaped menisci deepen the surface and spread load, while the cruciates and collaterals control sliding and side-to-side stress. The femur and tibia meet at a slight angle, giving normal knee valgus.",
  flow:["Convex femoral condyles sit on flat tibial plateaus","Menisci deepen surface and share load","Cruciates control front-back sliding","Collaterals resist valgus and varus stress","Roll and glide combine during flexion","Axes explain normal valgus and load distribution"],
  exam:[
    {h:"Introduction", p:["Modified hinge (double condyloid) joint with 2 degrees of freedom: flexion-extension and, in flexion, medial-lateral rotation.","Largest joint in the body; poorly congruent, so stability depends on soft tissues."]},
    {h:"Menisci", p:["Medial meniscus: C-shaped, wider posteriorly, attached to the MCL and semimembranosus, less mobile, so injured more often.","Lateral meniscus: nearly O-shaped, more mobile, attached to popliteus and meniscofemoral ligaments, not attached to LCL.","Functions: increase congruence, transmit about half or more of the load in extension, shock absorption, joint stability, lubrication and proprioception.","Blood supply only in the outer third (red zone); inner part (white zone) heals poorly."]},
    {h:"Ligaments", p:["ACL: from anterior intercondylar tibia to medial side of lateral femoral condyle; anteromedial and posterolateral bundles; resists anterior tibial translation, hyperextension and rotation.","PCL: from posterior intercondylar tibia to lateral side of medial femoral condyle; resists posterior tibial translation; stronger than ACL.","MCL: superficial and deep parts; main valgus restraint at 30 degrees flexion. LCL: cord-like, resists varus; with posterolateral corner and popliteus controls lateral rotation.","Capsule, posterior oblique ligament, iliotibial band and hamstrings add stability."]},
    {h:"Axes and alignment", p:["Anatomical axis of femur runs along the shaft and is inclined medially; the tibial shaft is nearly vertical, giving a physiological valgus of about 5-7 degrees (lateral tibiofemoral angle about 170-175 degrees; medial angle about 185 degrees).","Mechanical (weight-bearing) axis runs from the centre of the femoral head to the centre of the ankle, normally passing through or slightly medial to the centre of the knee.","Genu valgum: angle increased, mechanical axis shifts lateral; genu varum: axis shifts medial, overloading medial compartment.","Flexion-extension axis passes through the femoral condyles and shifts during motion; longitudinal rotation axis is near the medial intercondylar tubercle."]},
    {h:"Arthrokinematics and range", p:["Open chain flexion: tibia rolls and glides posteriorly; closed chain flexion (squatting): femur rolls posteriorly and glides anteriorly, guided by cruciates.","Range: flexion about 130-140 degrees, extension 0 with up to 5-10 degrees hyperextension; rotation at 90 degrees flexion: lateral about 40-45, medial about 25-30 degrees.","Close-packed position: full extension with lateral rotation of tibia."]},
    {h:"Applied aspects and conclusion", p:["ACL tear (non-contact pivot), unhappy triad (ACL, MCL and medial meniscus), meniscal tear with locking, varus knee OA.","Physiotherapy: quadriceps and hamstring strengthening, neuromuscular training, prehab before ACL reconstruction, load management for OA.","Menisci and ligaments make an incongruent joint stable; axes explain where load and degeneration concentrate."]}
  ],
  tip:"Draw a superior view of the tibial plateau with the C-shaped medial and O-shaped lateral menisci and ACL and PCL stumps. Next to it draw the whole lower limb showing anatomical axis of femur, tibial axis, the 5-7 degree valgus, and the mechanical axis from hip centre to ankle centre.",
  evidence:[["Exercise therapy versus arthroscopic partial meniscectomy for degenerative tears","Similar outcomes in middle-aged patients","High"],["Neuromuscular training to prevent ACL injury","Reduces ACL injury rates in athletes","Moderate"]],
  evidenceSource:"Levangie and Norkin; Neumann, Kinesiology of the Musculoskeletal System; randomised trials and systematic reviews on degenerative meniscal tears",
  outcomes:[["Lachman and anterior drawer","ACL integrity"],["McMurray and Thessaly tests","Meniscal tear"],["Valgus and varus stress tests","MCL and LCL"],["KOOS or Lysholm","Knee function"]],
  recent:["Guidelines now advise against routine arthroscopic surgery for degenerative meniscal tears in middle-aged patients, favouring exercise therapy first."],
  mnemonic:{word:"LAMP", items:[["L","Lateral condyle, medial side: ACL attaches"],["A","Anterior tibial translation resisted by ACL"],["M","Medial condyle, lateral side: PCL attaches"],["P","Posterior translation resisted by PCL"]], extra:"Medial meniscus is fixed to MCL so tears more; lateral is mobile and spared."},
  example:"A 24-year-old footballer in Kochi twists his knee on a planted foot, hears a pop and the knee swells within hours. Lachman test is positive; he starts prehab before ACL reconstruction.",
  flags:["Rapid haemarthrosis after twisting injury: ACL tear or fracture","True locking of the knee: displaced bucket handle meniscal tear","Knee dislocation: check popliteal artery and peroneal nerve"],
  viva:[["Why is the medial meniscus injured more often?","It is firmly attached to the capsule and MCL, so it is less mobile."],["Normal tibiofemoral angle?","About 5-7 degrees of physiological valgus (lateral angle about 170-175 degrees)."],["What does the ACL prevent?","Anterior translation of the tibia on the femur, plus hyperextension and rotational instability."]],
  refs:[{b:"levangie", ch:"The Knee"},{b:"neumann", ch:"Knee"},{b:"brunnstrom", ch:"Knee"}],
  keywords:["tibiofemoral","menisci","ACL","PCL","mechanical axis","valgus"],
  mcq:[["Which meniscus is attached to the medial collateral ligament?",["Lateral meniscus","Medial meniscus","Both","Neither"],1,"The medial meniscus is bound to the deep MCL, reducing its mobility."],["The mechanical axis of the lower limb passes from",["ASIS to medial malleolus","Greater trochanter to lateral malleolus","Centre of femoral head to centre of ankle","Iliac crest to heel"],2,"The weight-bearing line runs from the femoral head centre to the ankle centre."]]
},
{
  id:"bk-screw-home", title:"Locking and unlocking of the knee (screw-home mechanism)", subject:"Kinesiology", region:"Knee", stages:"steps",
  aliases:["screw home mechanism","locking of knee","unlocking of knee","terminal rotation","popliteus","automatic rotation"],
  simple:"In the last part of straightening the knee, the tibia twists slightly outward on the femur (or the femur twists inward on a fixed tibia). This twist locks the knee so we can stand with little muscle effort. The popliteus muscle unlocks it by twisting it back before the knee can bend.",
  flow:["Medial femoral condyle is longer than lateral","Lateral condyle finishes rolling first","Medial condyle keeps gliding in last 30 degrees","Tibia rotates laterally about 10 degrees","Ligaments tighten and the knee locks","Popliteus rotates back to unlock"],
  exam:[
    {h:"Definition", p:["Screw-home mechanism: conjunct (automatic) rotation of the knee during the final about 20-30 degrees of extension; lateral rotation of the tibia on the femur in open chain, or medial rotation of the femur on the tibia in closed chain.","Amount: about 10 degrees (quoted range 5-10 or more)."]},
    {h:"Causes of locking", p:["Medial femoral condyle has a longer articular surface than the lateral condyle; the lateral side completes its motion first and the medial side continues, causing rotation.","Tension in the ACL and other ligaments as the knee nears extension guides the rotation.","Lateral pull of the quadriceps and shape of the tibial intercondylar tubercles contribute."]},
    {h:"Effects of locking", p:["Close-packed position: maximum congruence, cruciate and collateral ligaments taut, menisci compressed.","Knee becomes a rigid column; standing needs little quadriceps activity because the line of gravity passes anterior to the knee axis.","Saves energy in prolonged standing."]},
    {h:"Unlocking", p:["Popliteus initiates unlocking: in closed chain it laterally rotates the femur on the tibia; in open chain it medially rotates the tibia on the femur.","Popliteus also pulls the lateral meniscus backward, protecting it during flexion.","Hamstrings then continue flexion."]},
    {h:"Clinical relevance", p:["Loss of terminal extension (ACL deficiency, meniscal tear, effusion, quadriceps lag, OA) prevents locking, causing quadriceps fatigue and abnormal joint loading.","Patients with quadriceps weakness (post-polio) may hyperextend to lock the knee mechanically (genu recurvatum).","Physiotherapy: terminal knee extension exercises (band around knee, 10-15 repetitions), quadriceps setting, patellar mobilisation, closed chain strengthening; correct extension deficit early after ACL reconstruction."]},
    {h:"Conclusion", p:["The screw-home mechanism is a built-in lock that gives stability at minimal cost; restoring full extension is a priority in knee rehabilitation."]}
  ],
  tip:"Draw an inferior view of the femoral condyles showing the longer medial condyle with a curved arrow. Draw a second sketch of the tibia rotating laterally in the last 30 degrees and label popliteus as the unlocking muscle.",
  evidence:[["Early restoration of full extension after ACL reconstruction","Linked to better outcomes and less anterior knee pain","Moderate"],["Terminal knee extension exercise","Common in protocols; direct trials limited","Low"]],
  evidenceSource:"Levangie and Norkin; Neumann, Kinesiology of the Musculoskeletal System; ACL rehabilitation guidelines",
  outcomes:[["Goniometry of extension","Extension deficit"],["Extensor lag test","Quadriceps control of terminal range"],["Prone heel height difference","Small loss of extension"]],
  recent:["Motion analysis and imaging studies show screw-home rotation varies between individuals and is altered after ACL injury and in knee OA."],
  mnemonic:{word:"LEMON", items:[["L","Lateral rotation of tibia"],["E","End of extension"],["M","Medial condyle longer"],["O","Opens with pOpliteus"],["N","No muscle needed to stand"]], extra:"Closed chain: femur rotates medially on fixed tibia."},
  example:"A 40-year-old teacher in Pondicherry with a flap meniscal tear cannot fully straighten her knee, so it never locks; she feels quadriceps fatigue after standing in class.",
  flags:["Sudden loss of extension with locking: displaced meniscal tear","Extension lag after surgery not improving: check quadriceps inhibition and effusion","Forced hyperextension to lock in weak quadriceps can damage posterior capsule"],
  viva:[["Which muscle unlocks the knee?","Popliteus."],["Why does the tibia rotate laterally in terminal extension?","The medial femoral condyle has a longer articular surface, so the medial side keeps gliding after the lateral side stops."],["In closed chain, what rotates during locking?","The femur rotates medially on the fixed tibia."]],
  refs:[{b:"levangie", ch:"The Knee"},{b:"neumann", ch:"Knee"},{b:"brunnstrom", ch:"Knee"}],
  keywords:["screw home","locking","unlocking","popliteus","terminal extension","conjunct rotation"],
  mcq:[["The muscle that unlocks the knee is",["Biceps femoris","Popliteus","Gastrocnemius","Sartorius"],1,"Popliteus rotates the femur laterally on the tibia (closed chain) to unlock."],["During open chain terminal knee extension the tibia",["Rotates medially","Rotates laterally","Does not rotate","Glides posteriorly"],1,"The tibia rotates laterally on the femur, locking the joint."]]
},
{
  id:"bk-knee-injury-effects", title:"Effects of injury and disease on the knee complex", subject:"Kinesiology", region:"Knee", stages:"011234",
  aliases:["knee pathomechanics","effects of injury knee","quadriceps inhibition","genu valgum varum","knee effusion","knee OA biomechanics"],
  simple:"When a knee ligament, meniscus or cartilage is damaged, the knee loses its normal guidance and load sharing. Swelling switches off the quadriceps, and the joint tends to stiffen in slight flexion. Over time abnormal loading can lead to deformity and osteoarthritis.",
  flow:["Injury or disease damages a knee structure","Stability, load sharing or congruence is lost","Effusion inhibits quadriceps and fixes knee flexed","Instability, locking, deformity or pain appear","Assess with special tests, alignment and function","Rehab restores range, strength and neuromuscular control"],
  exam:[
    {h:"Introduction", p:["The knee depends on soft tissues for stability; injury or disease changes arthrokinematics, load distribution and muscle function.","Effects can be grouped as effects of effusion, ligament injury, meniscal injury, cartilage disease and malalignment."]},
    {h:"Effusion and immobilisation", p:["Joint swelling causes arthrogenic muscle inhibition of quadriceps (reflex inhibition), giving extensor lag and wasting of vastus medialis.","Intra-articular pressure is lowest at about 30 degrees of flexion, so a swollen knee is held flexed; this risks flexion contracture.","Immobilisation leads to cartilage thinning, capsular shortening, ligament weakening and muscle atrophy."]},
    {h:"Ligament injuries", p:["ACL deficiency: anterior tibial translation and rotational instability (pivot shift, giving way), increased meniscal and cartilage damage over time.","PCL deficiency: posterior sag, increased patellofemoral and medial compartment load.","MCL injury: valgus instability; LCL and posterolateral corner injury: varus and lateral rotation instability, varus thrust in gait."]},
    {h:"Meniscal injury and cartilage disease", p:["Meniscal tear or meniscectomy reduces contact area, raising contact stress (removal of whole meniscus can greatly increase peak stress), leading to early OA.","Bucket handle tear causes locking and loss of extension; screw-home is lost.","Osteoarthritis: medial compartment is commonly affected; varus deformity increases the knee adduction moment, creating a vicious cycle of load and wear.","Rheumatoid arthritis: synovitis, ligament laxity, valgus deformity and flexion contracture."]},
    {h:"Malalignment and neuromuscular disease", p:["Genu valgum overloads lateral compartment and stretches medial structures; genu varum overloads medial compartment.","Genu recurvatum in quadriceps weakness (polio), plantarflexion contracture or ligament laxity.","Hemiplegia: knee hyperextension in stance or stiff knee gait; patellar instability with increased Q angle."]},
    {h:"Physiotherapy principles and conclusion", p:["Control effusion (cryotherapy 15-20 minutes, compression, elevation), quadriceps activation (setting, SLR, NMES 35-50 Hz if inhibition persists), restore full extension early.","Progress to closed chain strengthening (mini squats, step ups, 3 sets of 10-15), neuromuscular and balance training, gait re-education, bracing or lateral wedge insoles where indicated, weight loss in OA.","Small changes in alignment, stability or swelling have large effects on knee function, so early targeted rehab prevents secondary degeneration."]}
  ],
  tip:"Draw a flowchart: injury or disease, then effusion leading to quadriceps inhibition and flexed posture, then abnormal loading leading to OA. Beside it sketch a varus knee with the ground reaction force passing medial to the knee to show the adduction moment.",
  evidence:[["Exercise therapy for knee OA","Reduces pain and improves function","High"],["NMES added to exercise after ACL reconstruction","Improves early quadriceps strength","Moderate"],["Lateral wedge insoles for medial knee OA","Little or no clinically important pain benefit","Moderate"]],
  evidenceSource:"Cochrane review of exercise for knee OA; OARSI guidelines; Levangie and Norkin; Neumann",
  outcomes:[["Girth and sweep test","Effusion and wasting"],["Extension lag","Quadriceps inhibition"],["KOOS or WOMAC","Function in injury and OA"],["Single leg hop tests","Return to sport readiness"]],
  recent:["OARSI and other guidelines place exercise, education and weight management as core treatment for knee OA, with surgery reserved for late stages."],
  mnemonic:{word:"SLAM", items:[["S","Swelling inhibits quadriceps"],["L","Ligament loss causes instability"],["A","Alignment change shifts load"],["M","Meniscus loss raises contact stress"]], extra:"Swollen knee sits at about 30 degrees flexion."},
  example:"A 58-year-old vegetable vendor in Salem with medial knee OA has a varus thrust while walking. Quadriceps and hip abductor strengthening, weight loss advice and a walking stick in the opposite hand reduce her pain.",
  flags:["Hot red swollen knee with fever: septic arthritis","Knee dislocation or multiligament injury: check pulses and peroneal nerve","Calf pain and swelling after knee surgery: DVT"],
  viva:[["Why is a swollen knee held in slight flexion?","Intra-articular pressure and capsular tension are lowest at about 30 degrees of flexion."],["What is arthrogenic muscle inhibition?","Reflex inhibition of quadriceps caused by joint swelling or damage."],["Effect of meniscectomy on contact stress?","Contact area falls and peak stress rises, predisposing to OA."]],
  refs:[{b:"levangie", ch:"The Knee"},{b:"neumann", ch:"Knee"},{b:"brunnstrom", ch:"Knee"}],
  keywords:["effusion","quadriceps inhibition","ACL deficiency","meniscectomy","varus","knee OA"],
  mcq:[["A knee with effusion is most comfortable at about",["0 degrees","30 degrees flexion","90 degrees flexion","120 degrees flexion"],1,"Intra-articular pressure is lowest near 30 degrees flexion."],["Varus knee alignment mainly overloads the",["Lateral compartment","Patellofemoral joint only","Medial compartment","Proximal tibiofibular joint"],2,"The load line shifts medially, increasing medial compartment stress."]]
},
{
  id:"bk-ankle-foot-joints", title:"Joints of the ankle and foot: ankle, subtalar, transverse tarsal, TMT, MTP and IP joints", subject:"Kinesiology", region:"Ankle and foot", stages:"steps",
  aliases:["ankle joint biomechanics","talocrural joint","subtalar joint","midtarsal joint","Chopart joint","Lisfranc joint","joints of foot"],
  simple:"The ankle (talocrural) joint is a hinge that mainly moves the foot up and down. Below it, the subtalar and midtarsal joints let the foot tilt in and out so it can grip uneven ground. The joints of the forefoot and toes help us push off and balance when we walk.",
  flow:["Talocrural hinge gives dorsiflexion and plantarflexion","Subtalar joint gives inversion and eversion","Transverse tarsal joint adapts midfoot to ground","TMT joints adjust the forefoot rays","MTP joints extend for push-off","IP joints help toes grip and balance"],
  exam:[
    {h:"Introduction", p:["The ankle-foot complex has 28 bones and over 30 joints that must be both a flexible adaptor on uneven ground and a rigid lever for push-off.","Key joints: talocrural, subtalar, transverse tarsal (talonavicular plus calcaneocuboid), tarsometatarsal, metatarsophalangeal and interphalangeal."]},
    {h:"Talocrural (ankle) joint", p:["Synovial hinge: mortise formed by tibial plafond, medial malleolus and lateral malleolus receiving the trochlea of the talus.","Axis runs obliquely from just below the lateral malleolus to just below the medial malleolus, so dorsiflexion brings some abduction and eversion (pronation component) and plantarflexion some adduction and inversion.","Range: dorsiflexion about 10-20 degrees, plantarflexion about 40-50 degrees.","Talus is wider anteriorly: dorsiflexion is the close-packed, most stable position; plantarflexion is loose, so most sprains occur in plantarflexion plus inversion.","Ligaments: medial deltoid (strong) and lateral ATFL, CFL and PTFL; ATFL is injured most often."]},
    {h:"Subtalar joint", p:["Between talus and calcaneus with posterior, middle and anterior facets; sinus tarsi and the interosseous talocalcaneal ligament separate the compartments.","Single oblique axis (about 42 degrees from the horizontal and 16 degrees from the midline of the foot) produces triplanar supination and pronation.","Inversion about twice eversion in range; adapts the foot to sloping ground and converts leg rotation into foot motion."]},
    {h:"Transverse tarsal (midtarsal, Chopart) joint", p:["Talonavicular (ball and socket like) plus calcaneocuboid (saddle) joints.","Two axes, longitudinal and oblique; when the subtalar joint is pronated the axes are parallel and the midfoot is mobile, when supinated they converge and the midfoot locks.","This locking turns the foot into a rigid lever for push-off; the spring (plantar calcaneonavicular) ligament supports the talar head."]},
    {h:"TMT, intermetatarsal, MTP and IP joints", p:["TMT (Lisfranc) joints: plane joints allowing small flexion-extension of the rays; the second metatarsal base is keyed into a recess, making it the most stable ray.","MTP joints: condyloid; extension (about 70-90 degrees at the great toe) is needed for normal push-off; tightening the plantar aponeurosis in toe extension raises the arch (windlass mechanism).","IP joints: hinge joints for toe flexion and extension; toes help balance and grip in stance."]},
    {h:"Applied aspects and physiotherapy", p:["Inversion ankle sprain (ATFL), Pott's fracture, Lisfranc injury, hallux rigidus (loss of MTP extension) and hallux valgus.","Assessment: goniometry of dorsiflexion (knee bent and straight), subtalar neutral, first MTP extension, weight-bearing lunge test.","Treatment: joint mobilisation (talocrural posterior glide for dorsiflexion), calf stretching 3 x 30 seconds, balance and proprioceptive training 10-15 minutes daily, peroneal and intrinsic strengthening, footwear or orthoses."]},
    {h:"Conclusion", p:["Coordinated motion of these joints lets the foot change from a mobile adaptor at heel strike to a rigid lever at toe off."]}
  ],
  tip:"Draw the ankle mortise from the front with the talus inside and the oblique axis line; beside it draw a medial view of the foot labelling talocrural, subtalar, talonavicular, calcaneocuboid, TMT, MTP and IP joints with arrows for their main movements.",
  evidence:[["Ankle joint mobilisation with exercise after sprain","Improves dorsiflexion range in the short term","Moderate"],["Balance and proprioceptive training","Reduces recurrence of ankle sprain","Moderate"],["Foot orthoses for altered foot mechanics","Variable effects; individual selection needed","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function; Neumann, Kinesiology of the Musculoskeletal System; ankle sprain clinical practice guidelines",
  outcomes:[["Weight-bearing lunge test","Functional ankle dorsiflexion"],["Goniometry of first MTP extension","Toe-off capacity"],["Foot and Ankle Ability Measure (FAAM)","Function in daily and sport activities"]],
  recent:["Clinical practice guidelines for lateral ankle sprain recommend early weight-bearing, exercise and balance training rather than prolonged immobilisation."],
  mnemonic:{word:"TSTTMI", items:[["T","Talocrural: hinge, DF and PF"],["S","Subtalar: inversion and eversion"],["T","Transverse tarsal: locks and unlocks midfoot"],["T","TMT: ray movements"],["M","MTP: extension for push-off"],["I","IP: toe grip"]], extra:"Dorsiflexion is the close-packed position of the ankle."},
  example:"A 21-year-old kabaddi player in Madurai twists his ankle in plantarflexion and inversion; the ATFL is tender and dorsiflexion is reduced by 10 degrees compared with the other side.",
  flags:["Inability to bear weight four steps or bony malleolar tenderness: rule out fracture (Ottawa rules)","Midfoot swelling and plantar bruising after a twist: suspect Lisfranc injury","Hot swollen foot in a diabetic with little pain: suspect Charcot neuroarthropathy"],
  viva:[["Close-packed position of the ankle?","Full dorsiflexion, because the wider anterior talus wedges into the mortise."],["What is the windlass mechanism?","Extension of the toes tightens the plantar aponeurosis and raises the medial arch."],["Which joints make up Chopart's joint?","Talonavicular and calcaneocuboid joints."]],
  refs:[{b:"levangie", ch:"The Ankle and Foot Complex"},{b:"neumann", ch:"Ankle and Foot"},{b:"brunnstrom", ch:"Ankle and Foot"}],
  keywords:["talocrural","subtalar","midtarsal","Chopart","Lisfranc","MTP","windlass","ankle mortise"],
  mcq:[["The most stable (close-packed) position of the talocrural joint is",["Full plantarflexion","Neutral","Full dorsiflexion","Inversion"],2,"The wider anterior talus wedges into the mortise in dorsiflexion."],["Chopart's joint consists of",["Talonavicular and calcaneocuboid joints","Tarsometatarsal joints","Talocalcaneal and talonavicular joints","Intermetatarsal joints"],0,"The transverse tarsal (Chopart) joint combines talonavicular and calcaneocuboid joints."]]
},
{
  id:"bk-foot-arches", title:"Arches of the foot: formation, maintenance and functions", subject:"Kinesiology", region:"Ankle and foot", stages:"steps",
  aliases:["arches of foot","medial longitudinal arch","lateral longitudinal arch","transverse arch","plantar aponeurosis","windlass mechanism"],
  simple:"The foot bones are arranged like curved bridges called arches, not a flat plate. The arches act like springs that absorb shock and store energy, and they turn the foot into a stiff lever when we push off. Bones, ligaments and muscles all help hold them up.",
  flow:["Bones shaped into medial, lateral and transverse arches","Keystones: talus head and cuboid","Ligaments and plantar aponeurosis act as tie beams","Muscles support arch during activity","Arches absorb shock and spread load","Windlass mechanism stiffens arch at push-off"],
  exam:[
    {h:"Definition", p:["Arches are the curved arrangements of the tarsal and metatarsal bones that make the sole concave, giving a spring-like, weight-distributing structure.","Three arches: medial longitudinal, lateral longitudinal and transverse."]},
    {h:"Bony formation", p:["Medial longitudinal arch: calcaneus, talus, navicular, three cuneiforms and medial three metatarsals; highest arch; talar head is the keystone; posterior pillar is the calcaneal tuberosity and anterior pillars are the medial three metatarsal heads.","Lateral longitudinal arch: calcaneus, cuboid and lateral two metatarsals; low and rests on the ground in standing; cuboid is the keystone.","Transverse arch: formed by the bases of metatarsals, cuboid and cuneiforms (complete only when both feet are together); intermediate cuneiform is its keystone; it flattens at the metatarsal heads."]},
    {h:"Factors maintaining the arches", p:["Bony shape: wedge-shaped bones, especially cuneiforms and keystones.","Ligaments (tie beams and staples): spring ligament supports the talar head; long and short plantar ligaments support the lateral arch; interosseous ligaments.","Plantar aponeurosis acts as a tie beam (truss) between the calcaneus and toes.","Muscles: tibialis posterior, tibialis anterior, flexor hallucis longus and flexor digitorum longus support the medial arch; peroneus longus acts as a sling for the transverse and lateral arches; intrinsic foot muscles act as dynamic supports.","Muscles are not needed in quiet standing (EMG is low) but become important in walking, running and fatigue."]},
    {h:"Functions", p:["Distribute body weight to heel and metatarsal heads.","Shock absorption and storing elastic energy during running.","Adaptation to uneven ground (mobile foot) and rigid lever for propulsion.","Protect plantar nerves and vessels in the concavity."]},
    {h:"Windlass mechanism and applied aspects", p:["Extension of the MTP joints at toe off winds the plantar aponeurosis around the metatarsal heads, raising the arch and supinating the hindfoot.","Pes planus (flat foot: flexible or rigid), pes cavus (high arch), posterior tibial tendon dysfunction, plantar fasciitis, metatarsalgia when transverse arch falls.","Assessment: navicular drop test, Feiss line, footprint, Jack's toe raise test, single heel raise.","Physiotherapy: intrinsic foot strengthening (short foot exercise, towel curls 2-3 sets of 10-15), tibialis posterior strengthening, calf stretching, barefoot balance, arch supports or medial wedges when indicated."]},
    {h:"Conclusion", p:["Arches combine bones, ligaments, fascia and muscles so the foot can be both a spring and a lever; loss of arch support changes loading up the whole limb."]}
  ],
  tip:"Draw a medial view of the foot showing the medial longitudinal arch with talus marked as keystone and the plantar aponeurosis as a string from calcaneus to toes; add a small cross section at the cuneiforms for the transverse arch with peroneus longus as a sling.",
  evidence:[["Short foot (intrinsic) exercise","Improves arch height and foot control in flat foot in small trials","Low to moderate"],["Foot orthoses for painful flexible flat foot","May reduce pain short term","Low"],["Calf stretching and loading for plantar heel pain","Supported in plantar fasciitis guidelines","Moderate"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin; plantar heel pain clinical practice guideline",
  outcomes:[["Navicular drop test","Dynamic fall of medial arch"],["Foot Posture Index","Overall pronated or supinated foot type"],["Footprint (arch index)","Arch contact area"]],
  recent:["Research on the foot core concept highlights intrinsic foot muscles as active arch supports that can be trained."],
  mnemonic:{word:"BLAM", items:[["B","Bones shaped as wedges"],["L","Ligaments: spring, long and short plantar"],["A","Aponeurosis tie beam"],["M","Muscles: tibialis posterior, peroneus longus sling"]], extra:"Keystones: talar head (medial), cuboid (lateral), intermediate cuneiform (transverse)."},
  example:"A 35-year-old traffic constable in Chennai who stands for hours develops medial foot pain; the navicular drops 12 mm on standing and he cannot do a single heel raise well.",
  flags:["Painful unilateral acquired flat foot in a middle-aged adult: posterior tibial tendon dysfunction","Rigid flat foot in a child or teenager: rule out tarsal coalition","Progressive cavus foot: screen for neurological cause such as CMT disease"],
  viva:[["Keystone of the medial longitudinal arch?","Head of the talus."],["Which muscle forms a sling for the transverse arch?","Peroneus longus, with tibialis posterior and anterior."],["What is the windlass mechanism?","Toe extension tightens the plantar aponeurosis, raising the arch."]],
  refs:[{b:"neumann", ch:"Ankle and Foot"},{b:"levangie", ch:"The Ankle and Foot Complex"},{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Arches of the Foot"}],
  keywords:["medial longitudinal arch","lateral arch","transverse arch","keystone","spring ligament","plantar aponeurosis","windlass"],
  mcq:[["The keystone of the lateral longitudinal arch is the",["Talus","Navicular","Cuboid","Calcaneus"],2,"The cuboid is the keystone of the lateral longitudinal arch."],["The ligament that directly supports the head of the talus is the",["Long plantar ligament","Spring (plantar calcaneonavicular) ligament","Deltoid ligament","Short plantar ligament"],1,"The spring ligament forms a sling under the talar head."]]
},
{
  id:"bk-foot-movements", title:"Movements of the foot: inversion, eversion, pronation and supination", subject:"Kinesiology", region:"Ankle and foot", stages:"steps",
  aliases:["pronation of foot","supination of foot","inversion eversion","triplanar motion","subtalar pronation","foot movements"],
  simple:"Inversion turns the sole inward and eversion turns it outward. Pronation and supination are combined movements in three planes at once. Pronation makes the foot soft and flexible to absorb shock, and supination makes it stiff for pushing off.",
  flow:["Movement happens mainly at subtalar and midtarsal joints","Oblique axis gives triplanar motion","Supination: inversion, adduction, plantarflexion","Pronation: eversion, abduction, dorsiflexion","Closed chain: talus and leg move over calcaneus","Pronation absorbs, supination propels"],
  exam:[
    {h:"Definitions", p:["Inversion: sole turns to face medially (frontal plane). Eversion: sole turns to face laterally.","Adduction and abduction: forefoot moves toward or away from the midline (transverse plane).","Supination (open chain): combined inversion, adduction and plantarflexion; pronation: combined eversion, abduction and dorsiflexion.","Terminology varies between texts; in exams state the definition you use."]},
    {h:"Joints and axes", p:["Talocrural joint contributes mainly dorsiflexion and plantarflexion.","Subtalar joint: oblique axis gives true triplanar pronation and supination.","Transverse tarsal joint adds forefoot motion and is locked in supination, mobile in pronation.","Ranges (approximate): inversion about 20-30 degrees, eversion about 10-15 degrees."]},
    {h:"Open versus closed chain", p:["Open chain (foot off the ground): calcaneus moves on the talus.","Closed chain (weight-bearing) pronation: calcaneus everts, talus adducts and plantarflexes, tibia rotates medially, knee tends to valgus.","Closed chain supination: calcaneus inverts, talus abducts and dorsiflexes, tibia rotates laterally.","Thus foot motion is coupled to leg and hip rotation (the subtalar joint acts like a mitred hinge)."]},
    {h:"Muscles", p:["Invertors and supinators: tibialis posterior (main), tibialis anterior, FHL, FDL, gastrocnemius-soleus via the calcaneus.","Evertors and pronators: peroneus longus, peroneus brevis, peroneus tertius, extensor digitorum longus."]},
    {h:"Function in gait and applied aspects", p:["After heel strike the foot pronates to absorb shock and adapt to the ground; from midstance to toe off it supinates to become a rigid lever.","Excess or prolonged pronation: medial tibial stress, plantar fasciitis, patellofemoral pain, hallux valgus; excess supination: poor shock absorption, lateral ankle sprain, stress fractures.","Assessment: subtalar neutral, rearfoot angle, navicular drop, Foot Posture Index, gait observation.","Physiotherapy: strengthen tibialis posterior and intrinsics, peroneal strengthening and balance after inversion sprain, calf flexibility, orthoses or footwear changes."]},
    {h:"Conclusion", p:["Pronation and supination are triplanar, closed-chain coupled movements that let the foot alternate between shock absorber and lever."]}
  ],
  tip:"Draw a posterior view of a right heel in three positions: vertical (neutral), tilted inward (inversion) and outward (eversion). Next to it draw a table listing the three components of pronation and supination in the three planes.",
  evidence:[["Foot orthoses in excessive pronation with pain","Small, variable benefit; better for some conditions than others","Low"],["Neuromuscular and balance training after inversion sprain","Reduces recurrence","Moderate"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Levangie and Norkin; ankle sprain clinical practice guidelines",
  outcomes:[["Foot Posture Index","Degree of pronation or supination"],["Rearfoot angle","Calcaneal eversion in standing"],["Star Excursion Balance Test","Dynamic control after ankle injury"]],
  recent:["Three dimensional gait analysis shows wide normal variation in foot pronation, so foot type alone poorly predicts injury."],
  mnemonic:{word:"PEAD", items:[["P","Pronation ="],["E","Eversion"],["A","Abduction"],["D","Dorsiflexion"]], extra:"Supination is the opposite: inversion, adduction, plantarflexion."},
  example:"A 19-year-old nursing student in Salem with shin pain on long ward duty shows marked heel eversion and navicular drop when she stands; her tibia rotates medially as the foot pronates.",
  flags:["Sudden painful loss of inversion strength with flat foot: tibialis posterior tendon rupture","Fixed varus foot with weakness: neurological cause","Repeated giving way after sprain: chronic ankle instability needs specialist evaluation"],
  viva:[["Components of open chain pronation?","Eversion, abduction and dorsiflexion."],["Main invertor of the foot?","Tibialis posterior."],["What happens to the tibia during closed chain pronation?","It rotates medially."]],
  refs:[{b:"neumann", ch:"Ankle and Foot"},{b:"levangie", ch:"The Ankle and Foot Complex"},{b:"magee", ch:"Lower Leg, Ankle and Foot"}],
  keywords:["pronation","supination","inversion","eversion","subtalar","closed chain","triplanar"],
  mcq:[["Open chain supination of the foot consists of",["Eversion, abduction, dorsiflexion","Inversion, adduction, plantarflexion","Inversion, abduction, dorsiflexion","Eversion, adduction, plantarflexion"],1,"Supination combines inversion, adduction and plantarflexion."],["During closed chain pronation the tibia",["Rotates laterally","Rotates medially","Does not move","Translates posteriorly"],1,"Subtalar pronation is coupled with medial tibial rotation."]]
},
{
  id:"bk-foot-muscles", title:"Extrinsic and intrinsic muscles of the foot: actions and functions", subject:"Kinesiology", region:"Ankle and foot", stages:"steps",
  aliases:["muscles of foot","extrinsic foot muscles","intrinsic foot muscles","plantar layers of foot","foot core","calf muscles"],
  simple:"Extrinsic foot muscles start in the leg and send long tendons to the foot; they move the ankle and toes and hold up the arches. Intrinsic muscles lie inside the foot in four layers on the sole and help the toes and the arches during standing and walking.",
  flow:["Extrinsic muscles in anterior, lateral and posterior compartments","Anterior group dorsiflexes and controls foot drop","Lateral group everts and supports transverse arch","Posterior group plantarflexes and inverts","Intrinsic muscles in four plantar layers","Intrinsics stabilise arch and toes in stance"],
  exam:[
    {h:"Introduction", p:["Extrinsic muscles originate in the leg and insert in the foot; intrinsic muscles both originate and insert within the foot.","Together they move the foot, control the arches and give propulsion and balance."]},
    {h:"Extrinsic: anterior and lateral compartments", p:["Anterior (deep peroneal nerve, L4-L5): tibialis anterior (dorsiflexion and inversion; eccentric control after heel strike), extensor hallucis longus, extensor digitorum longus, peroneus tertius.","Lateral (superficial peroneal nerve, L5-S1): peroneus longus (eversion, plantarflexion of first ray, sling for transverse arch) and peroneus brevis (eversion, lateral ankle stability).","Weak dorsiflexors cause foot drop and high-stepping gait; weak peronei add to lateral ankle instability."]},
    {h:"Extrinsic: posterior compartment", p:["Superficial (tibial nerve, S1-S2): gastrocnemius, soleus and plantaris through the tendo calcaneus; main plantarflexors, propulsion at push-off and control of forward tibial movement in midstance.","Deep (tibial nerve): tibialis posterior (main invertor, supports medial arch), flexor digitorum longus, flexor hallucis longus (push-off from great toe), popliteus at the knee.","Tendons pass behind the medial malleolus in order: Tibialis posterior, flexor Digitorum longus, Artery, Nerve, flexor Hallucis longus (Tom, Dick And Nervous Harry)."]},
    {h:"Intrinsic muscles (four plantar layers plus dorsum)", p:["Layer 1: abductor hallucis, flexor digitorum brevis, abductor digiti minimi.","Layer 2: quadratus plantae and lumbricals, with FDL and FHL tendons.","Layer 3: flexor hallucis brevis, adductor hallucis, flexor digiti minimi brevis.","Layer 4: plantar and dorsal interossei (with peroneus longus and tibialis posterior tendons). Dorsum: extensor digitorum brevis and extensor hallucis brevis.","Nerve supply: medial and lateral plantar nerves (tibial), extensor digitorum brevis by deep peroneal nerve. Intrinsics stiffen the arch, stabilise toes and fine-tune balance."]},
    {h:"Applied aspects and physiotherapy", p:["Foot drop (common peroneal palsy, L5 radiculopathy), Achilles tendinopathy and rupture, tibialis posterior dysfunction, intrinsic weakness causing claw toes (diabetic neuropathy).","Assessment: MMT, heel and toe walking, single leg heel raise (normal about 20-25 repetitions), Thompson test.","Treatment: progressive calf loading (eccentric heel drops 3 x 15, twice daily, in Achilles tendinopathy), tibialis posterior strengthening, short foot and towel exercises, ankle-foot orthosis for foot drop, FES of dorsiflexors in central lesions."]},
    {h:"Conclusion", p:["Extrinsic muscles provide motion and power while intrinsics provide arch and toe stability; both are needed for normal gait and balance."]}
  ],
  tip:"Draw a cross section of the leg showing anterior, lateral and posterior compartments with their nerves, then a sole of the foot with four layers listed beside it. Mark the medial malleolus tendon order with the mnemonic.",
  evidence:[["Progressive loading (eccentric or heavy slow resistance) for Achilles tendinopathy","Reduces pain and improves function","Moderate"],["Ankle-foot orthosis for foot drop","Improves walking speed and safety","Moderate"],["Intrinsic foot muscle training","Improves foot strength and arch control in small trials","Low"]],
  evidenceSource:"Neumann, Kinesiology of the Musculoskeletal System; Kendall, Muscles Testing and Function; Achilles tendinopathy clinical practice guideline",
  outcomes:[["Single leg heel raise test","Calf endurance"],["Manual muscle testing","Strength of individual muscles"],["VISA-A","Achilles tendinopathy severity"]],
  recent:["The foot core concept describes intrinsic muscles as local stabilisers of the arch, and has led to more use of intrinsic training in rehabilitation."],
  mnemonic:{word:"Tom Dick And Nervous Harry", items:[["T","Tibialis posterior"],["D","flexor Digitorum longus"],["A","posterior tibial Artery"],["N","tibial Nerve"],["H","flexor Hallucis longus"]], extra:"Order of structures behind the medial malleolus, front to back."},
  example:"A 45-year-old farmer from Villupuram develops foot drop after sitting cross-legged for long hours in the fields; tibialis anterior and peronei are weak and he trips on uneven bunds.",
  flags:["Sudden pop at the back of the heel with weak push-off: Achilles rupture (Thompson test)","Foot drop with back pain and sensory loss: L5 radiculopathy or cauda equina screen","Tense painful calf after injury: compartment syndrome"],
  viva:[["Main invertor of the foot?","Tibialis posterior."],["Nerve to extensor digitorum brevis?","Deep peroneal nerve."],["Muscles of the first plantar layer?","Abductor hallucis, flexor digitorum brevis, abductor digiti minimi."]],
  refs:[{b:"neumann", ch:"Ankle and Foot"},{b:"kendall", ch:"Lower Extremity Muscles"},{c:"Chaurasia BD. Human Anatomy, Volume 2: Lower Limb, Abdomen and Pelvis. Chapter: Sole of the Foot"}],
  keywords:["tibialis anterior","peroneus longus","gastrocnemius","soleus","tibialis posterior","plantar layers","intrinsic muscles"],
  mcq:[["Which muscle lies in the second layer of the sole?",["Abductor hallucis","Quadratus plantae","Adductor hallucis","Dorsal interossei"],1,"Quadratus plantae and lumbricals form the second layer."],["Foot drop after fibular neck injury is due to paralysis of muscles supplied by the",["Tibial nerve","Deep peroneal nerve","Medial plantar nerve","Sural nerve"],1,"The deep peroneal nerve supplies the dorsiflexors."]]
},
{
  id:"bk-posture-line-of-gravity", title:"Optimal posture: line of gravity and gravitational moments", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["line of gravity","ideal posture","standing posture","optimal posture","plumb line","gravitational moments"],
  simple:"Good standing posture keeps body segments stacked so that the line of gravity passes close to the joints. Then gravity creates only small turning forces that ligaments and a little muscle work can easily balance. This saves energy and protects joints.",
  flow:["Centre of gravity lies just anterior to S2","Line of gravity drops vertically to base of support","Passes close to each joint axis","Small gravitational moments created at each joint","Balanced by ligaments and low muscle activity","Deviations raise muscle work and tissue stress"],
  exam:[
    {h:"Definition", p:["Posture is the alignment of body segments at a given moment; optimal (ideal) posture is the alignment that needs minimal muscle effort and places least stress on joints and soft tissues.","Line of gravity (LOG): vertical line passing through the body's centre of gravity, located roughly anterior to the second sacral vertebra in standing."]},
    {h:"LOG in lateral view (sagittal plane)", p:["Head: anterior to the atlanto-occipital joint, through or near the external auditory meatus; flexion moment balanced by posterior neck muscles.","Cervical spine: passes through or just posterior to the vertebral bodies; extension moment.","Thoracic spine: anterior to the vertebrae; flexion moment resisted by posterior ligaments and erector spinae.","Lumbar spine: through or just posterior to the bodies; extension moment resisted by the anterior longitudinal ligament.","Hip: slightly posterior to the hip axis (near the greater trochanter); extension moment resisted by iliofemoral ligament.","Knee: slightly anterior to the knee axis; extension moment resisted by posterior capsule and ligaments.","Ankle: slightly anterior to the lateral malleolus; dorsiflexion moment controlled by soleus and gastrocnemius."]},
    {h:"LOG in anterior and posterior view (frontal plane)", p:["LOG divides the body into equal halves: through the middle of the head, sternum, umbilicus, pubic symphysis and between the knees and ankles.","Weight shared equally between both feet; head, shoulders, iliac crests and knees level."]},
    {h:"Muscle and ligament roles", p:["Standing is maintained mostly by passive structures plus low-level tonic activity of soleus, erector spinae, neck extensors and to a small extent iliopsoas and gluteus medius.","Postural sway (anteroposterior) is normal and is controlled by ankle and hip strategies.","Any deviation (forward head, increased lordosis) moves the LOG away from joint axes, lengthening the moment arm and increasing muscle and ligament load."]},
    {h:"Factors affecting posture and physiotherapy relevance", p:["Factors: structural defects, muscle imbalance, pain, fatigue, obesity, pregnancy, habits (mobile phone use), footwear, occupation, emotional state.","Assessment with a plumb line in lateral and posterior views.","Physiotherapy: postural education, ergonomic advice, stretching tight muscles (pectorals, hip flexors) 3 x 30 seconds, strengthening deep neck flexors, scapular retractors and core 2-3 sets of 10-15, frequent position change."]},
    {h:"Conclusion", p:["Optimal posture keeps the LOG close to joint axes so that standing is energy-efficient; knowing its normal path is the basis for every postural assessment."]}
  ],
  tip:"Draw a lateral stick figure with a vertical dashed plumb line and label where it passes: ear lobe, shoulder (acromion), bodies of lumbar vertebrae, just behind hip, just in front of knee, just in front of lateral malleolus. Write the moment produced at each joint beside it.",
  evidence:[["Postural correction exercise for forward head posture","Small improvements in alignment and neck pain","Low to moderate"],["Ergonomic interventions at work","Mixed evidence for preventing musculoskeletal pain","Low"]],
  evidenceSource:"Levangie and Norkin, Joint Structure and Function: Posture; Kendall, Muscles Testing and Function: Posture",
  outcomes:[["Plumb line assessment","Deviation from ideal alignment"],["Craniovertebral angle on photograph","Forward head posture"],["Flexicurve or inclinometer","Thoracic kyphosis and lumbar lordosis"]],
  recent:["Current evidence suggests no single posture is ideal for everyone; varying posture and staying active matter more than a perfect static position."],
  mnemonic:{word:"EAR-SHOULDER-TROCHANTER-KNEE-ANKLE", items:[["E","Ear lobe"],["S","Shoulder tip (acromion)"],["T","Greater trochanter (just behind hip axis)"],["K","Just in front of knee axis"],["A","Just in front of lateral malleolus"]], extra:"Hip extension moment, knee extension moment, ankle dorsiflexion moment."},
  example:"A 20-year-old BPT student in Coimbatore studying on her phone for hours has a forward head; the LOG passes well in front of her cervical spine and she gets neck ache by evening.",
  flags:["Postural pain with night pain or weight loss: rule out serious pathology","Rapidly progressive deformity in an adolescent: refer for scoliosis evaluation","Postural change with neurological signs: needs medical evaluation"],
  viva:[["Where does the LOG pass in relation to the knee?","Slightly anterior to the knee joint axis, producing an extension moment."],["Which muscle is most active in quiet standing?","Soleus, controlling forward sway at the ankle."],["Where is the centre of gravity in adults?","Just anterior to the second sacral vertebra."]],
  refs:[{b:"levangie", ch:"Posture"},{b:"kendall", ch:"Posture: Alignment and Muscle Balance"},{b:"magee", ch:"Assessment of Posture"}],
  keywords:["line of gravity","posture","plumb line","gravitational moment","centre of gravity","sway"],
  mcq:[["In optimal standing posture the line of gravity passes",["Posterior to the knee","Anterior to the knee","Through the patella","Posterior to the lateral malleolus"],1,"It passes slightly anterior to the knee axis, creating an extension moment."],["The gravitational moment at the hip in optimal standing is resisted mainly by",["Iliofemoral ligament","Gluteus maximus","Hamstrings","Ligamentum teres"],0,"The LOG falls behind the hip, creating an extension moment checked by the iliofemoral ligament."]]
},
{
  id:"bk-postural-analysis", title:"Postural analysis: anterior, posterior and lateral views", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["postural assessment","posture analysis","plumb line test","observation of posture","lateral view posture","posterior view posture"],
  simple:"Postural analysis means looking at a person standing from the front, back and side against a plumb line or grid. We check whether body landmarks are level and lined up. This helps find muscle imbalance, deformity or habits that cause pain.",
  flow:["Explain, expose and stand patient barefoot","Hang plumb line or use posture grid","Check anterior view landmarks for symmetry","Check posterior view: spine, scapulae, heels","Check lateral view against plumb line","Record deviations and link to muscle imbalance"],
  exam:[
    {h:"Introduction and preparation", p:["Postural analysis is a systematic observation of standing alignment compared with an ideal reference line.","Patient in minimal clothing, barefoot, standing relaxed with feet about 7-10 cm apart; good light; plumb line or grid behind; photographs if possible.","Note general build, body type and any obvious asymmetry first."]},
    {h:"Anterior view", p:["Plumb line should pass midway between the feet and through the nose, chin, sternum, umbilicus and pubic symphysis.","Check: head tilt or rotation, level of shoulders and clavicles, arm position and carrying angles, level of ASIS and iliac crests, patellae (squinting or frog-eye patella), genu valgum or varum, tibial torsion, foot position, arches and toes (hallux valgus)."]},
    {h:"Posterior view", p:["Plumb line through the occiput, spinous processes, gluteal cleft and midway between the knees and heels.","Check: head position, shoulder levels, scapulae (winging, elevation, abduction, distance from spine), lateral spinal curve (scoliosis), rib hump on forward bending (Adam's test), waist angles, PSIS and gluteal folds, popliteal creases, calcaneal alignment (valgus or varus), Achilles tendon."]},
    {h:"Lateral view", p:["Plumb line slightly anterior to the lateral malleolus should pass slightly anterior to the knee axis, slightly posterior to the hip axis (through greater trochanter), through lumbar bodies, shoulder joint and the ear lobe.","Check: forward head, rounded shoulders, thoracic kyphosis, lumbar lordosis or flat back, sway back, pelvic tilt (ASIS-PSIS relation), genu recurvatum or flexed knees.","Common postural faults (Kendall): kyphosis-lordosis, flat back, sway back, forward head."]},
    {h:"Interpretation and physiotherapy", p:["Link findings to muscle imbalance, for example anterior pelvic tilt with tight hip flexors and lumbar extensors and weak abdominals and gluteals (lower crossed pattern); forward head with tight upper trapezius and pectorals and weak deep neck flexors (upper crossed pattern).","Confirm with leg length measurement, muscle length tests (Thomas test, pectoralis minor length) and strength tests.","Plan: correct habits, stretch short muscles, strengthen weak ones, ergonomic advice, footwear or orthoses; re-photograph to measure progress."]},
    {h:"Conclusion", p:["A structured three-view analysis against a plumb line turns observation into objective findings that guide treatment."]}
  ],
  tip:"Draw three stick figures side by side (anterior, posterior, lateral) each with a dashed plumb line, and label two or three key landmarks the line should pass through in each view. Add one common fault beside each.",
  evidence:[["Visual postural assessment","Moderate reliability; better with photographs and landmarks","Low to moderate"],["Photogrammetry (posture software on photographs)","More reliable than visual estimation for many angles","Moderate"]],
  evidenceSource:"Kendall, Muscles Testing and Function: Posture; Magee, Orthopedic Physical Assessment: Assessment of Posture",
  outcomes:[["Photogrammetric angles (craniovertebral angle)","Forward head"],["Adam's forward bend test with scoliometer","Rotational deformity in scoliosis"],["Leg length measurement","Structural or functional asymmetry"]],
  recent:["Free smartphone posture-photo apps and grid backgrounds are widely used in clinics to record posture objectively."],
  mnemonic:{word:"APL", items:[["A","Anterior: symmetry of levels"],["P","Posterior: spine, scapula, heel"],["L","Lateral: plumb line and curves"]], extra:"Always check from head to toe in the same order."},
  example:"A 16-year-old girl from Tirunelveli is brought for a 'bent back'; the posterior view shows a right shoulder higher, an uneven waist angle and a rib hump on forward bending.",
  flags:["Rib hump or progressive curve in an adolescent: scoliosis referral","Painful scoliosis or rapid progression: rule out tumour or infection","Sudden kyphotic deformity in an elderly person: osteoporotic fracture"],
  viva:[["Where should the plumb line pass in the lateral view at the ankle?","Slightly anterior to the lateral malleolus."],["What does Adam's forward bend test show?","Rib hump due to vertebral rotation in structural scoliosis."],["Name Kendall's common postural faults.","Kyphosis-lordosis, flat back, sway back and forward head."]],
  refs:[{b:"kendall", ch:"Posture: Alignment and Muscle Balance"},{b:"magee", ch:"Assessment of Posture"},{b:"levangie", ch:"Posture"}],
  keywords:["postural analysis","plumb line","anterior view","posterior view","lateral view","postural faults"],
  mcq:[["Adam's forward bending test is used to detect",["Lumbar disc prolapse","Rib hump in scoliosis","Spondylolisthesis","Sacroiliac dysfunction"],1,"Forward bending reveals the rotational rib hump of structural scoliosis."],["In posterior view analysis, the plumb line should pass through",["The spinous processes and gluteal cleft","The left scapula","The right PSIS","The lateral malleolus"],0,"Posteriorly the line bisects the body through the spinous processes and gluteal cleft."]]
},
{
  id:"bk-gait-phases-parameters", title:"Gait cycle phases (stance, swing, double support) and gait parameters", subject:"Kinesiology", region:"Whole body", stages:"steps",
  aliases:["gait cycle","phases of gait","stance phase","swing phase","double support","stride length","cadence"],
  simple:"A gait cycle runs from one heel strike to the next heel strike of the same leg. About 60 percent is stance, when the foot is on the ground, and 40 percent is swing. Gait parameters like cadence, step length and speed measure how someone walks.",
  flow:["Gait cycle starts at initial contact","Stance about 60 percent of cycle","Swing about 40 percent of cycle","Two double support periods of about 10 percent","Measure step, stride, cadence, speed, width","Changes in parameters reveal pathology"],
  exam:[
    {h:"Definition", p:["Gait cycle: the interval from initial contact of one foot to the next initial contact of the same foot (one stride).","Normal walking: stance about 60 percent and swing about 40 percent of the cycle at normal speed."]},
    {h:"Phases (traditional and Rancho Los Amigos terms)", p:["Stance: heel strike (initial contact, 0 percent), foot flat (loading response, 0-10 percent), midstance (10-30 percent), heel off (terminal stance, 30-50 percent), toe off (pre-swing, 50-60 percent).","Swing: acceleration (initial swing, 60-73 percent), midswing (73-87 percent), deceleration (terminal swing, 87-100 percent).","Functional tasks: weight acceptance, single limb support, limb advancement."]},
    {h:"Double and single support", p:["Double support occurs twice: at loading response and at pre-swing, about 10 percent each (about 20 percent of the cycle).","Single limb support about 40 percent, equal to the swing time of the other limb.","Double support shortens as speed increases and disappears in running (replaced by a flight phase); it increases in elderly and unsteady patients."]},
    {h:"Gait parameters (approximate adult values)", p:["Step length: distance from heel of one foot to heel of the other foot, about 60-75 cm. Stride length: two steps, about 1.2-1.5 m.","Cadence: steps per minute, about 100-120. Walking speed: about 1.2-1.4 m/s (comfortable).","Step width (base of support): about 5-10 cm. Foot angle (toe out): about 5-7 degrees.","Vertical displacement of centre of mass about 5 cm and lateral about 4-5 cm, minimised by the determinants of gait."]},
    {h:"Assessment and physiotherapy relevance", p:["Observational gait analysis, 10-metre walk test, footprint method for step and stride, video analysis and instrumented walkways.","Asymmetry of step length or stance time suggests pain (antalgic), weakness or neurological disease; walking speed below about 0.8 m/s limits community walking.","Training: treadmill and overground walking, cueing cadence with a metronome, part-practice of phases, balance and strength training, walking aids."]},
    {h:"Conclusion", p:["Knowing the phases and normal parameters of gait allows the physiotherapist to detect, measure and treat abnormal walking."]}
  ],
  tip:"Draw a horizontal bar marked 0-100 percent, divide it at 60 percent into stance and swing, shade the two double support periods (0-10 and 50-60 percent), and label the eight Rancho phases above with stick figure legs below.",
  evidence:[["Walking speed as a clinical measure","Strong predictor of function and survival in older adults","High"],["Task-specific treadmill and overground gait training after stroke","Improves walking speed and distance","Moderate"]],
  evidenceSource:"Perry J, Gait Analysis: Normal and Pathological Function; Levangie and Norkin: Gait; Neumann: Kinesiology of Walking",
  outcomes:[["10-metre walk test","Walking speed"],["Cadence and step length from footprints","Spatial and temporal gait parameters"],["Dynamic Gait Index","Gait under changing demands"]],
  recent:["Wearable inertial sensors and smartphone apps now measure cadence, step length and gait variability outside the laboratory."],
  mnemonic:{word:"I Love My Tea Pot In My Tummy", items:[["I","Initial contact"],["L","Loading response"],["M","Midstance"],["T","Terminal stance"],["P","Pre-swing"],["I","Initial swing"],["M","Mid swing"],["T","Terminal swing"]], extra:"Stance 60, swing 40, double support 10 plus 10."},
  example:"A 68-year-old retired postman in Thanjavur after a fall walks with short steps, wide base and longer double support; his 10-metre walk speed is 0.7 m/s.",
  flags:["Sudden change in gait with headache or weakness: urgent neurological review","Repeated falls or very slow speed: falls risk assessment","Painful limp with fever in a child: rule out septic arthritis"],
  viva:[["What percentage of the gait cycle is stance?","About 60 percent at normal speed."],["Difference between step and stride length?","Step is heel to opposite heel; stride is heel to the same heel (two steps)."],["What happens to double support in running?","It disappears and a flight phase appears."]],
  refs:[{b:"levangie", ch:"Gait"},{b:"neumann", ch:"Kinesiology of Walking"},{c:"Perry J, Burnfield JM. Gait Analysis: Normal and Pathological Function. Chapter: Gait Cycle", q:"Perry gait analysis normal and pathological function"}],
  keywords:["gait cycle","stance","swing","double support","step length","stride","cadence","walking speed"],
  mcq:[["Double support in normal walking occupies about",["5 percent","20 percent","40 percent","60 percent"],1,"Two periods of about 10 percent each."],["Cadence is measured as",["Metres per second","Steps per minute","Centimetres between heels","Degrees of toe out"],1,"Cadence is the number of steps per minute."]]
},
{
  id:"bk-gait-joint-motion", title:"Kinematics of gait: joint motion at the hip, knee, ankle and pelvis during walking", subject:"Kinesiology", region:"Lower limb", stages:"steps",
  aliases:["joint angles during gait","gait kinematics","hip knee ankle in gait","ankle rockers","determinants of gait","sagittal plane gait"],
  simple:"While we walk, the hip, knee and ankle move through a set pattern of bending and straightening each cycle. The ankle acts as three rockers in stance, the knee bends a little to absorb shock and a lot to clear the foot, and the hip swings forward and back. Knowing normal angles helps us spot abnormal walking.",
  flow:["Hip flexed 30 degrees at initial contact","Hip extends to about 10-20 degrees in terminal stance","Knee flexes 15-20 degrees in loading response","Knee flexes about 60 degrees in initial swing","Ankle plantarflexes then dorsiflexes in stance","Ankle plantarflexes about 20 degrees at toe off"],
  exam:[
    {h:"Introduction", p:["Gait kinematics describe joint angles through the gait cycle; sagittal plane motion is largest and most examined.","Approximate values from Perry and Rancho Los Amigos; individual values vary."]},
    {h:"Hip", p:["Initial contact: about 30 degrees flexion.","Stance: extends steadily to about 10-20 degrees extension (apparent) by terminal stance.","Pre-swing and swing: flexes, reaching about 30-35 degrees in mid-terminal swing. Total sagittal excursion about 40-45 degrees.","Frontal plane: slight adduction in stance (pelvic drop controlled by gluteus medius); transverse rotation a few degrees."]},
    {h:"Knee", p:["Initial contact: near full extension (about 0-5 degrees flexion).","Loading response: flexes to about 15-20 degrees for shock absorption (quadriceps eccentric).","Midstance to terminal stance: extends to near 0-5 degrees.","Pre-swing: flexes to about 35-40 degrees. Initial swing: peak flexion about 60-70 degrees for foot clearance; extends again in terminal swing (hamstrings decelerate)."]},
    {h:"Ankle (three rockers)", p:["Initial contact: neutral (0 degrees).","Heel (first) rocker: plantarflexes about 5-10 degrees to foot flat, controlled eccentrically by dorsiflexors.","Ankle (second) rocker: tibia advances over the foot, dorsiflexion to about 10 degrees by terminal stance, controlled eccentrically by soleus and gastrocnemius.","Forefoot (third) rocker: heel rises and ankle plantarflexes to about 15-20 degrees at toe off; returns to neutral in midswing for clearance.","First MTP extends to about 55-60 degrees in pre-swing."]},
    {h:"Pelvis, trunk and determinants of gait", p:["Pelvic rotation about 4 degrees each side (8 degrees total), pelvic list (drop) about 5 degrees on the swing side, lateral shift of pelvis.","Determinants of gait (Saunders): pelvic rotation, pelvic tilt, knee flexion in stance, foot and ankle mechanisms (two), lateral pelvic displacement; they reduce vertical and lateral COM displacement and save energy.","Arms swing opposite to legs; trunk counter-rotates."]},
    {h:"Clinical relevance and physiotherapy", p:["Loss of knee flexion in swing causes circumduction or hip hiking; loss of ankle dorsiflexion causes early heel rise or foot drop with steppage; hip flexion contracture shortens step length.","Assess by observational gait analysis with video, goniometry of required ranges (ankle DF 10 degrees, knee flexion 60 degrees, hip extension 10 degrees).","Treatment: restore required ranges (stretching, mobilisation), strengthen key muscles, orthoses (AFO), gait training with feedback."]},
    {h:"Conclusion", p:["Each joint has a typical angle pattern; deviations from it are the basis of pathological gait analysis."]}
  ],
  tip:"Draw three small graphs (hip, knee, ankle) with percent gait cycle 0-100 on the x axis and degrees on the y axis, marking the peaks: hip 30 flexion to 10 extension, knee double hump (20 then 60), ankle PF-DF-PF pattern. Label the three rockers on the ankle graph.",
  evidence:[["Ankle-foot orthosis in foot drop","Improves ankle kinematics in swing and walking speed","Moderate"],["Gait training with visual or video feedback","Can improve specific joint deviations","Low to moderate"]],
  evidenceSource:"Perry J, Gait Analysis: Normal and Pathological Function; Neumann: Kinesiology of Walking; Levangie and Norkin: Gait",
  outcomes:[["Observational gait analysis (Rancho form)","Joint deviations by phase"],["Goniometry of functional ranges","Whether required ranges are available"],["3D motion analysis","Precise joint angles"]],
  recent:["Markerless video-based motion capture using smartphone cameras is being validated for clinical gait kinematics."],
  mnemonic:{word:"30-60-20", items:[["30","Hip flexion at initial contact"],["60","Peak knee flexion in initial swing"],["20","Ankle plantarflexion at toe off"]], extra:"Ankle rockers: heel, ankle, forefoot."},
  example:"A 55-year-old man in Vellore with a stiff knee after a fracture cannot bend beyond 40 degrees; in swing he hikes the hip and circumducts to clear the foot.",
  flags:["New foot drop or steppage gait: check for nerve or spinal cause","Hip pain with altered gait in children: screen for Perthes disease or SUFE","Abrupt freezing or shuffling: neurological review"],
  viva:[["How much knee flexion is needed for normal swing?","About 60-70 degrees."],["What are the three ankle rockers?","Heel rocker, ankle rocker and forefoot rocker."],["Name two determinants of gait.","Pelvic rotation and knee flexion in stance (others: pelvic tilt, ankle and foot mechanisms, lateral pelvic displacement)."]],
  refs:[{b:"neumann", ch:"Kinesiology of Walking"},{b:"levangie", ch:"Gait"},{c:"Perry J, Burnfield JM. Gait Analysis: Normal and Pathological Function. Chapter: Basic Functions", q:"Perry gait analysis normal and pathological function"}],
  keywords:["gait kinematics","hip","knee","ankle","rockers","determinants of gait","joint angles"],
  mcq:[["Peak knee flexion in the normal gait cycle (about 60-70 degrees) occurs in",["Loading response","Midstance","Initial swing","Terminal swing"],2,"Maximum knee flexion is in initial swing for foot clearance."],["The second (ankle) rocker is controlled mainly by eccentric activity of the",["Tibialis anterior","Soleus and gastrocnemius","Peroneus brevis","Quadriceps"],1,"Calf muscles control forward tibial advance over the fixed foot."]]
}
]);
